// Advect the previous frame through a continuous flow field. The waveform is
// drawn separately: its history can keep curling after the sound has changed.
const vertexSource = `
attribute vec2 position;
varying vec2 uv;
void main() {
  uv = position * 0.5 + 0.5;
  gl_Position = vec4(position, 0.0, 1.0);
}`;

const fragmentSource = `
precision mediump float;
uniform sampler2D history;
uniform vec2 resolution;
uniform float elapsed;
uniform float time;
uniform vec4 flow;
varying vec2 uv;
void main() {
  vec2 aspect = vec2(resolution.x / resolution.y, 1.0);
  vec2 center = vec2(sin(time * 0.13), cos(time * 0.11)) * 0.065;
  vec2 p = (uv - 0.5) * aspect - center;
  float r = length(p);
  float turn = flow.y + flow.z * sin(r * 5.0 - time * 0.19);
  vec2 velocity = p * flow.x + vec2(-p.y, p.x) * turn;
  // Two interleaved curls bend straight traces into rippling sheets. Working
  // in height units keeps the flow round on wide and portrait displays.
  velocity += flow.z * vec2(
    sin(p.y * 5.0 + time * 0.23) * cos(p.x * 2.0 - time * 0.17),
    cos(p.x * 4.0 - time * 0.21) * sin(p.y * 3.0 + time * 0.13)
  );
  velocity += flow.w * vec2(p.x, -p.y);
  vec2 source = (p - velocity * elapsed + center) / aspect + 0.5;
  vec3 color = texture2D(history, clamp(source, 0.0, 1.0)).rgb;
  vec2 texel = 1.0 / resolution;
  vec3 neighbors = texture2D(history, clamp(source + vec2(texel.x, 0.0), 0.0, 1.0)).rgb
    + texture2D(history, clamp(source - vec2(texel.x, 0.0), 0.0, 1.0)).rgb
    + texture2D(history, clamp(source + vec2(0.0, texel.y), 0.0, 1.0)).rgb
    + texture2D(history, clamp(source - vec2(0.0, texel.y), 0.0, 1.0)).rgb;
  // A little sharpening preserves the fine wave edges through repeated warps.
  color = max(vec3(0.0), color * 1.08 - neighbors * 0.02);
  float inside = step(0.0, source.x) * step(source.x, 1.0)
    * step(0.0, source.y) * step(source.y, 1.0);
  // Subtract a small floor as well as fading, so 8-bit trails reach true black.
  color = max(vec3(0.0), color * exp(-elapsed * 0.42) - elapsed * 0.018);
  gl_FragColor = vec4(color * inside, 1.0);
}`;

export type Flow = readonly [number, number, number, number];

export function createVisualizerFeedback(source: HTMLCanvasElement) {
  const canvas = document.createElement("canvas");
  const gl = canvas.getContext("webgl", {
    alpha: false,
    antialias: false,
    depth: false,
    stencil: false,
    premultipliedAlpha: false,
  });
  if (!gl) return undefined;

  const shaders: WebGLShader[] = [];
  const program = gl.createProgram();
  const texture = gl.createTexture();
  const buffer = gl.createBuffer();
  let lost = false;
  let allocated = false;
  const onContextLost = () => {
    lost = true;
  };
  canvas.addEventListener("webglcontextlost", onContextLost);
  const dispose = () => {
    canvas.removeEventListener("webglcontextlost", onContextLost);
    shaders.forEach((shader) => gl.deleteShader(shader));
    gl.deleteProgram(program);
    gl.deleteBuffer(buffer);
    gl.deleteTexture(texture);
    // This is a private, disposable context; release its GPU allocation now.
    gl.getExtension("WEBGL_lose_context")?.loseContext();
  };
  if (!program || !texture || !buffer) {
    dispose();
    return undefined;
  }
  for (const [type, code] of [
    [gl.VERTEX_SHADER, vertexSource],
    [gl.FRAGMENT_SHADER, fragmentSource],
  ] as const) {
    const shader = gl.createShader(type);
    if (!shader) {
      dispose();
      return undefined;
    }
    shaders.push(shader);
    gl.shaderSource(shader, code);
    gl.compileShader(shader);
    if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
      dispose();
      return undefined;
    }
    gl.attachShader(program, shader);
  }
  gl.linkProgram(program);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    dispose();
    return undefined;
  }
  gl.useProgram(program);
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  gl.bufferData(
    gl.ARRAY_BUFFER,
    new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]),
    gl.STATIC_DRAW,
  );
  const position = gl.getAttribLocation(program, "position");
  gl.enableVertexAttribArray(position);
  gl.vertexAttribPointer(position, 2, gl.FLOAT, false, 0, 0);
  gl.bindTexture(gl.TEXTURE_2D, texture);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
  gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, true);
  gl.uniform1i(gl.getUniformLocation(program, "history"), 0);
  const resolution = gl.getUniformLocation(program, "resolution");
  const elapsedUniform = gl.getUniformLocation(program, "elapsed");
  const timeUniform = gl.getUniformLocation(program, "time");
  const flowUniform = gl.getUniformLocation(program, "flow");

  return {
    draw(elapsed: number, time: number, flow: Flow) {
      if (lost || gl.isContextLost()) return undefined;
      if (
        !allocated ||
        canvas.width !== source.width ||
        canvas.height !== source.height
      ) {
        canvas.width = source.width;
        canvas.height = source.height;
        gl.viewport(0, 0, canvas.width, canvas.height);
        gl.texImage2D(
          gl.TEXTURE_2D,
          0,
          gl.RGB,
          gl.RGB,
          gl.UNSIGNED_BYTE,
          source,
        );
        allocated = true;
      } else {
        gl.texSubImage2D(
          gl.TEXTURE_2D,
          0,
          0,
          0,
          gl.RGB,
          gl.UNSIGNED_BYTE,
          source,
        );
      }
      gl.uniform2f(resolution, canvas.width, canvas.height);
      gl.uniform1f(elapsedUniform, elapsed);
      gl.uniform1f(timeUniform, time);
      gl.uniform4f(flowUniform, ...flow);
      gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
      return canvas;
    },
    dispose,
  };
}
