import { Center } from "@mantine/core";
import { IconFolder, IconMovie, IconMusic } from "@tabler/icons-react";
import { useEffect, useState } from "react";
import { getThumbnail } from "@/domain/Utils";

/** A consistent, compact thumbnail for native and browser library lists. */
export function LibraryThumbnail({
  thumbnails = [],
  name,
  folder,
  audioOnly,
}: {
  thumbnails?: string[];
  name: string;
  folder?: boolean;
  audioOnly?: boolean;
}) {
  const small = thumbnails.find((path) => /[._]160\.jpg$/.test(path));
  const src = getThumbnail(small ? [small] : thumbnails, 160);
  const [failed, setFailed] = useState(false);
  useEffect(() => setFailed(false), [src]);
  const Icon = folder ? IconFolder : audioOnly ? IconMusic : IconMovie;
  return (
    <Center
      w={88}
      h={56}
      bg="dark.5"
      sx={{ flexShrink: 0, borderRadius: 12, overflow: "hidden" }}
    >
      {src && !failed ? (
        <img
          src={src}
          alt={`Thumbnail for ${name}`}
          loading="lazy"
          onError={() => setFailed(true)}
          style={{ width: "100%", height: "100%", objectFit: "cover" }}
        />
      ) : (
        <Icon aria-hidden color="#8CE4CD" size={24} stroke={1.5} />
      )}
    </Center>
  );
}
