import { FC, useEffect, useRef } from "react";
import { useSelector } from "react-redux";
import { RootState } from "@/domain/Store";
import { Tooltip, Box, Loader, keyframes } from "@mantine/core";
import { HiOutlineStatusOnline, HiOutlineStatusOffline } from "react-icons/hi";
import { showWarningAlert, showInfoAlert } from "./Alert";

const pulse = keyframes({
  '0%': { opacity: 1 },
  '50%': { opacity: 0.4 },
  '100%': { opacity: 1 },
});

interface ConnectionIndicatorProps {
  size?: number;
  showWhenConnected?: boolean;
}

export const ConnectionIndicator: FC<ConnectionIndicatorProps> = ({
  size = 24,
  showWhenConnected = false
}) => {
  const { connectionStatus, reconnectAttempts } = useSelector(
    (state: RootState) => state.video
  );

  // Track previous status for notifications
  const prevStatusRef = useRef(connectionStatus);

  useEffect(() => {
    const prevStatus = prevStatusRef.current;

    // Show notification when status changes
    if (prevStatus !== connectionStatus) {
      if (connectionStatus === 'reconnecting' && prevStatus === 'connected') {
        showWarningAlert("Connection lost, reconnecting...");
      } else if (connectionStatus === 'connected' && prevStatus === 'reconnecting') {
        showInfoAlert("Reconnected successfully");
      }

      prevStatusRef.current = connectionStatus;
    }
  }, [connectionStatus]);

  // Don't render anything if connected and showWhenConnected is false
  if (connectionStatus === 'connected' && !showWhenConnected) {
    return null;
  }

  const getStatusConfig = () => {
    switch (connectionStatus) {
      case 'connected':
        return {
          icon: <HiOutlineStatusOnline size={size} color="green" />,
          tooltip: "Connected",
          color: "green",
        };
      case 'reconnecting':
        return {
          icon: (
            <Box sx={{ animation: `${pulse} 1.5s ease-in-out infinite` }}>
              <HiOutlineStatusOffline size={size} color="orange" />
            </Box>
          ),
          tooltip: `Reconnecting... (attempt ${reconnectAttempts})`,
          color: "orange",
        };
      case 'disconnected':
      default:
        return {
          icon: <HiOutlineStatusOffline size={size} color="red" />,
          tooltip: "Disconnected",
          color: "red",
        };
    }
  };

  const config = getStatusConfig();

  return (
    <Tooltip label={config.tooltip} position="bottom">
      <Box
        sx={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          cursor: 'default',
        }}
      >
        {config.icon}
      </Box>
    </Tooltip>
  );
};
