import { forwardRef, useImperativeHandle, useRef, useState } from "react";
import { flushSync } from "react-dom";
import {
  ActionIcon,
  Box,
  Group,
  NativeSelect,
  Paper,
  Stack,
  Text,
} from "@mantine/core";
import { IconX } from "@tabler/icons-react";
import { RestAdaptor } from "@/adaptors/Interfaces";
import {
  PlayRequest,
  RemoteMessage,
  RemotePlayerState,
  VideoDetails,
} from "@/domain/Messages";
import { PlaybackControls } from "@/services/Player";
import { localPlayRequest } from "@/services/mediaUrls";
import Player, { PlayerHandlers, PlayState } from "./Player";
import { AudioPlaybackControls } from "./AudioPlaybackControls";

export interface LocalPlaybackState {
  video: VideoDetails;
  state: RemotePlayerState;
}

export interface LocalPlaybackHandle extends PlaybackControls {
  pausePlayback: () => void;
}

export interface LocalPlaybackProps {
  host: RestAdaptor;
  active: boolean;
  onChange: (playback: LocalPlaybackState | undefined) => void;
  onStart: () => void;
}

interface Session {
  id: number;
  video: VideoDetails;
  request: PlayRequest;
}

// This session lives outside the TV's Redux state and survives navigation in Main.
export const LocalPlayback = forwardRef<
  LocalPlaybackHandle,
  LocalPlaybackProps
>(({ host, active, onChange, onStart }, ref) => {
  const playerRef = useRef<PlayerHandlers>(null);
  const nextId = useRef(0);
  const [session, setSession] = useState<Session>();
  const [subtitleTrack, setSubtitleTrack] = useState<number | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);

  useImperativeHandle(ref, () => ({
    playVideo: (video) => {
      const request = localPlayRequest(video, host);
      playerRef.current?.stop();
      // Mount and call play within the user's click, including on mobile.
      flushSync(() => {
        setSession({
          id: ++nextId.current,
          video: { ...video, url: request.url },
          request,
        });
        setSubtitleTrack(null);
        onChange({
          video: { ...video, url: request.url },
          state: {
            videoId: video.checksum,
            video: video.video,
            collection: video.collection,
            currentSrc: request.url,
            currentTime: 0,
            duration: video.metadata.duration,
            paused: true,
          },
        });
        onStart();
      });
      playerRef.current?.play();
    },
    seek: (interval) => playerRef.current?.seek(interval),
    togglePause: () => playerRef.current?.pause(),
    setSubtitleTrack: (trackId) => playerRef.current?.setSubtitleTrack(trackId),
    seekToSubtitle: (direction) => playerRef.current?.seekToSubtitle(direction),
    pausePlayback: () => playerRef.current?.stop(),
  }));

  if (!session) return null;

  const { video, request } = session;
  const audioOnly =
    /\.(mp3|m4a|aac|flac|wav|ogg|opus|wma)$/i.test(video.video) ||
    (request.width === 0 && request.height === 0);
  const audioTracks = request.metadata?.audioTrackList ?? [];
  const subtitleTracks = request.metadata?.subtitleTracks ?? [];

  const onMessage = (message: RemoteMessage) => {
    if (message.State) {
      setSubtitleTrack(message.State.currentSubtitleTrack ?? null);
      onChange({ video, state: message.State });
    }
  };

  const close = () => {
    playerRef.current?.stop();
    setSession(undefined);
    onChange(undefined);
  };

  return (
    <Paper
      role="region"
      aria-label="This device player"
      withBorder
      p="sm"
      mb="md"
      style={{
        display: active ? undefined : "none",
        position: "sticky",
        top: 0,
        zIndex: 20,
      }}
    >
      <Stack spacing="xs">
        <Group position="apart" noWrap>
          <Text size="sm" lineClamp={1}>
            {video.video}
          </Text>
          <ActionIcon aria-label="Close local player" onClick={close}>
            <IconX size={18} />
          </ActionIcon>
        </Group>
        <Box
          h={audioOnly ? "min(46vh, 380px)" : "min(42vh, 360px)"}
          sx={{ background: "#000" }}
        >
          <Player
            key={session.id}
            currentVideo={request}
            ref={playerRef}
            audioOnly={audioOnly}
            onStateChange={(state) => setIsPlaying(state === PlayState.STARTED)}
            onMessage={onMessage}
          />
        </Box>
        {audioOnly && (
          <AudioPlaybackControls
            isPlaying={isPlaying}
            togglePause={() => playerRef.current?.pause()}
            stop={close}
          />
        )}
        <Group key={session.id} spacing="xs" grow>
          <NativeSelect
            label="Speed"
            defaultValue="1"
            data={["0.5", "1", "1.25", "1.5", "2"].map((value) => ({
              value,
              label: `${value}×`,
            }))}
            onChange={(event) =>
              playerRef.current?.setPlaybackRate(
                Number(event.currentTarget.value),
              )
            }
          />
          {audioTracks.length > 1 && (
            <NativeSelect
              label="Audio track"
              defaultValue={String(
                audioTracks.find((track) => track.default)?.id ??
                  audioTracks[0].id,
              )}
              data={audioTracks.map((track) => ({
                value: String(track.id),
                label: track.label || track.language,
              }))}
              onChange={(event) =>
                playerRef.current?.setAudioTrack(
                  Number(event.currentTarget.value),
                )
              }
            />
          )}
          {subtitleTracks.length > 0 && (
            <NativeSelect
              label="Subtitles"
              value={subtitleTrack === null ? "off" : String(subtitleTrack)}
              data={[
                { value: "off", label: "Off" },
                ...subtitleTracks.map((track, index) => ({
                  value: String(index),
                  label: track.label || track.language,
                })),
              ]}
              onChange={(event) =>
                playerRef.current?.setSubtitleTrack(
                  event.currentTarget.value === "off"
                    ? null
                    : Number(event.currentTarget.value),
                )
              }
            />
          )}
        </Group>
      </Stack>
    </Paper>
  );
});
