import { forwardRef, useCallback } from "react";
import { useDispatch, useSelector } from "react-redux";
import { RootState } from "@/domain/Store";
import { RemoteMessage } from "@/domain/Messages";
import { socketSend } from "@/domain/Store/SocketMiddleware";
import { clearSeekEvent, setIsPlaying } from "@/domain/Store/VideoReducer";
import Player, { PlayerHandlers, PlayerProps, PlayState } from "./Player";

// Connect the shared media player to the TV's remote commands and reports.
const RemotePlayer = forwardRef<
  PlayerHandlers,
  Pick<PlayerProps, "currentVideo" | "onStateChange" | "audioOnly">
>((props, ref) => {
  const dispatch = useDispatch();
  const { isPlaying, seekEvent } = useSelector(
    (state: RootState) => state.video,
  );
  const onSeekHandled = useCallback(() => {
    dispatch(clearSeekEvent());
  }, [dispatch]);
  const onMessage = useCallback(
    (message: RemoteMessage) => {
      dispatch(socketSend(message));
    },
    [dispatch],
  );
  const onStateChange = (state: PlayState) => {
    dispatch(setIsPlaying(state === PlayState.STARTED));
    props.onStateChange(state);
  };

  return (
    <Player
      {...props}
      ref={ref}
      isPlaying={isPlaying}
      seekEvent={seekEvent}
      onSeekHandled={onSeekHandled}
      onMessage={onMessage}
      onStateChange={onStateChange}
    />
  );
});

export default RemotePlayer;
