import { ActionIcon, Group, Radio, Stack, TextInput } from "@mantine/core";
import { SE_PIRATEBAY, SE_YOUTUBE } from "../../domain/Constants";
import { IconArrowRight, IconSearch } from "@tabler/icons-react";
import { useDispatch, useSelector } from "react-redux";
import { AppDispatch, RootState } from "@/domain/Store";
import { setEngine, setTerm } from "@/domain/Store/SearchReducer";

export const SearchBox = ({
  doSearch,
}: {
  doSearch: (query: string, engine: string) => void;
}) => {
  const term = useSelector((state: RootState) => state.search.term);
  const engine = useSelector((state: RootState) => state.search.engine);
  const dispatch: AppDispatch = useDispatch();
  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        if (term) doSearch(term, engine);
      }}
    >
      <Stack spacing="md">
        <TextInput
          id="search-term"
          aria-label="Search videos"
          placeholder="What would you like to find?"
          icon={<IconSearch size={18} />}
          size="md"
          value={term}
          onChange={(event) => dispatch(setTerm(event.currentTarget.value))}
          rightSectionWidth={48}
          rightSection={
            <ActionIcon
              type="submit"
              aria-label="Find videos"
              variant="light"
              color="mint"
              size={36}
              disabled={!term}
            >
              <IconArrowRight size={19} />
            </ActionIcon>
          }
        />
        <Radio.Group
          value={engine}
          onChange={(value) => dispatch(setEngine(value))}
          aria-label="Search provider"
        >
          <Group spacing="xl">
            <Radio label="PirateBay" name="engine" value={SE_PIRATEBAY} />
            <Radio label="YouTube" name="engine" value={SE_YOUTUBE} />
          </Group>
        </Radio.Group>
      </Stack>
    </form>
  );
};
