/**
 * Typescript code consisting of a Modal component and a ModalStack class.
 * The Modal component renders a reusable modal with a transparent overlay background.
 */

import { Modal } from "@mantine/core";
import React, { ReactNode } from "react";

type CardModalProps = {
  title: string;
  children: ReactNode;
  onClose: () => void;
  centered?: boolean;
};

export const CardModal = (props: CardModalProps): JSX.Element => {
  return (
    <Modal
      padding="lg"
      size="auto"
      centered={props.centered ?? true}
      yOffset={24}
      styles={{
        content: { maxWidth: "calc(100vw - 24px)" },
        body: { minWidth: 0 },
      }}
      opened={true}
      onClose={props.onClose}
      closeButtonProps={{ "aria-label": "Close dialog" }}
      title={props.title}
    >
      {props.children}
    </Modal>
  );
};
