import { Box, DEFAULT_THEME, MantineProvider } from "@mantine/core";
import { ReactNode } from "react";
import { overrideTheme } from "@/theme";
import { legacyPlayerTheme } from "@/playerTheme";

/** Shared library appearance, including library overlays inside the HTML viewer. */
export function AppAppearance({ children }: { children: ReactNode }) {
  return (
    <MantineProvider theme={overrideTheme} inherit={false}>
      <Box
        className="media-app"
        sx={{ color: "#F3F7FB", fontSize: 15, lineHeight: 1.5 }}
      >
        {children}
      </Box>
    </MantineProvider>
  );
}

/** Keep the HTML player and its controls independent of library theme changes. */
export function LegacyPlayerAppearance({ children }: { children: ReactNode }) {
  return (
    <MantineProvider theme={legacyPlayerTheme} inherit={false}>
      <Box
        sx={{
          fontFamily: DEFAULT_THEME.fontFamily,
          fontSize: 16,
          lineHeight: "1.25rem",
          color: DEFAULT_THEME.black,
        }}
      >
        {children}
      </Box>
    </MantineProvider>
  );
}
