import { getCleanName } from "@/domain/Utils";
import {
  ActionIcon,
  Group,
  List,
  Menu,
  Text,
  UnstyledButton,
} from "@mantine/core";
import {
  IconChevronRight,
  IconDotsVertical,
  IconShare,
  IconTrash,
} from "@tabler/icons-react";
import { FC } from "react";
import { LibraryThumbnail } from "./LibraryThumbnail";
import { Player } from "@/services/Player";

interface ICollectionItem {
  isLast: boolean;
  name: string;
  thumbnails?: string[];
  collection?: string;
  onClick: () => void;
  player: Player;
}

export const CollectionItem: FC<ICollectionItem> = ({
  name,
  thumbnails,
  collection,
  onClick,
  player,
}) => {
  const key = collection ? `${collection}/${name}` : name;
  const displayName = name ? getCleanName(name) : "Others";
  return (
    <List.Item className="library-row">
      <Group noWrap spacing="sm">
        <UnstyledButton
          onClick={onClick}
          aria-label={`Open ${displayName}`}
          sx={{
            display: "flex",
            alignItems: "center",
            gap: 16,
            flex: 1,
            minWidth: 0,
            minHeight: 48,
          }}
        >
          <LibraryThumbnail thumbnails={thumbnails} name={displayName} folder />
          <Text
            weight={500}
            lineClamp={2}
            sx={{ flex: 1, overflowWrap: "anywhere" }}
          >
            {displayName}
          </Text>
          <IconChevronRight size={18} color="#B8C2CF" />
        </UnstyledButton>
        <Menu width={200}>
          <Menu.Target>
            <ActionIcon aria-label={`More actions for ${displayName}`}>
              <IconDotsVertical size={20} />
            </ActionIcon>
          </Menu.Target>
          <Menu.Dropdown>
            <Menu.Item
              onClick={() => player.shareVideo(name, key)}
              icon={<IconShare size={18} />}
            >
              Share
            </Menu.Item>
            <Menu.Divider />
            <Menu.Item
              color="red"
              onClick={() => player.deleteVideo(name, key)}
              icon={<IconTrash size={18} />}
            >
              Delete
            </Menu.Item>
          </Menu.Dropdown>
        </Menu>
      </Group>
    </List.Item>
  );
};
