import {
  forwardRef,
  useEffect,
  useImperativeHandle,
  useRef,
  useState,
} from "react";
import { Alert } from "@mantine/core";
import { invoke } from "@tauri-apps/api/core";
import { listen, UnlistenFn } from "@tauri-apps/api/event";
import {
  MediaDetails,
  RemotePlayerState,
  VideoDetails,
} from "@/domain/Messages";
import {
  LocalPlaybackHandle,
  LocalPlaybackProps,
  LocalPlaybackState,
} from "./LocalPlayback";

interface NativeState extends RemotePlayerState {
  closed?: boolean;
  error?: string;
}

export const NativePlayback = forwardRef<
  LocalPlaybackHandle,
  LocalPlaybackProps
>(({ host, active, onChange, onStart }, ref) => {
  const current = useRef<LocalPlaybackState & { state: NativeState }>();
  const listener = useRef<Promise<UnlistenFn>>();
  const pendingVideo = useRef<string>();
  const selectionVersion = useRef(0);
  const [error, setError] = useState("");

  useEffect(() => {
    let mounted = true;
    let events = 0;
    let latest: NativeState | undefined;
    let lookup:
      | { id: string; result: Promise<VideoDetails | undefined> }
      | undefined;
    const apply = (video: VideoDetails, payload: NativeState) => {
      if (!mounted) return;
      const playback = {
        video: { ...video, playFrom: payload.currentTime },
        state: payload,
      };
      current.current = playback;
      onChange(playback);
      if (payload.error) setError(payload.error);
    };
    const receive = (payload: NativeState) => {
      if (
        !payload.videoId ||
        (pendingVideo.current && pendingVideo.current !== payload.videoId)
      )
        return;
      pendingVideo.current = undefined;
      latest = payload;
      const video = current.current?.video;
      if (video?.checksum === payload.videoId) {
        apply(video, payload);
      } else {
        // A WebView can be recreated while the native foreground session lives on.
        // Rehydrate metadata without issuing a play/open command.
        if (lookup?.id !== payload.videoId) {
          lookup = {
            id: payload.videoId,
            result: host
              .get<MediaDetails>(`media/${encodeURIComponent(payload.videoId)}`)
              .then((details) => details.Collection?.videos[0]?.Video),
          };
        }
        const version = selectionVersion.current;
        void lookup.result
          .then((restored) => {
            if (
              restored &&
              mounted &&
              version === selectionVersion.current &&
              latest?.videoId === restored.checksum
            )
              apply(restored, latest);
          })
          .catch((reason) => {
            if (mounted) setError(String(reason));
          });
      }
    };
    const ready = listen<NativeState>("android-player-state", ({ payload }) => {
      events++;
      receive(payload);
    });
    listener.current = ready;
    void ready.catch((reason) => setError(String(reason)));
    const refresh = async () => {
      const version = selectionVersion.current;
      const received = events;
      try {
        await ready;
        const payload = await invoke<NativeState>("android_player_status");
        if (
          mounted &&
          version === selectionVersion.current &&
          received === events
        )
          receive(payload);
      } catch (reason) {
        if (mounted) setError(String(reason));
      }
    };
    const onVisible = () => {
      if (!document.hidden) void refresh();
    };
    void refresh();
    document.addEventListener("visibilitychange", onVisible);
    window.addEventListener("focus", onVisible);
    return () => {
      mounted = false;
      document.removeEventListener("visibilitychange", onVisible);
      window.removeEventListener("focus", onVisible);
      void ready.then((unlisten) => unlisten()).catch(() => {});
    };
  }, [host, onChange]);

  const control = (action: string, args: Record<string, unknown> = {}) => {
    void invoke("android_player_control", { action, ...args }).catch((reason) =>
      setError(String(reason)),
    );
  };

  const playVideo = (video: VideoDetails, startTime = video.playFrom ?? 0) => {
    selectionVersion.current++;
    pendingVideo.current = video.checksum;
    const playback = {
      video,
      state: {
        videoId: video.checksum,
        video: video.video,
        collection: video.collection,
        currentSrc: video.url ?? "",
        currentTime: startTime,
        duration: video.metadata.duration,
        paused: true,
      },
    };
    current.current = playback;
    setError("");
    onChange(playback);
    onStart();
    // Subscribe before starting the Activity so its first state cannot be missed.
    void (async () => {
      await listener.current;
      await invoke("android_player_open", {
        videoId: video.checksum,
        startTime,
      });
    })().catch((reason) => setError(String(reason)));
  };

  useImperativeHandle(ref, () => ({
    playVideo,
    seek: (seconds) => control("seek", { seconds }),
    togglePause: () => {
      const session = current.current;
      if (session?.state.closed) {
        playVideo(session.video, session.state.currentTime);
      } else {
        control("togglePause");
      }
    },
    pausePlayback: () => control("pause"),
    setSubtitleTrack: (track) => control("subtitle", { track: track ?? -1 }),
    seekToSubtitle: () =>
      setError(
        "Jumping between subtitle cues is not supported by this player yet.",
      ),
  }));

  if (!active || !error) return null;
  return (
    <Alert color="red" role="alert" mt="sm">
      {error}
    </Alert>
  );
});
