export interface AudioAnalysis {
  analyser: AnalyserNode;
  resume: () => void;
  dispose: () => void;
}

// Keep native playback intact until Web Audio is actually allowed to run.
export function createAudioAnalysis(
  media: HTMLMediaElement,
): AudioAnalysis | undefined {
  const AudioContextClass =
    window.AudioContext ??
    (window as Window & { webkitAudioContext?: typeof AudioContext })
      .webkitAudioContext;
  if (!AudioContextClass) return undefined;

  let context: AudioContext;
  try {
    context = new AudioContextClass();
  } catch {
    return undefined;
  }
  let analyser: AnalyserNode;
  try {
    analyser = context.createAnalyser();
    analyser.fftSize = 1024;
    analyser.smoothingTimeConstant = 0.3;
  } catch {
    void context.close().catch(() => {});
    return undefined;
  }

  let source: MediaElementAudioSourceNode | undefined;
  let disposed = false;
  const connect = () => {
    if (disposed || source || context.state !== "running") return;
    try {
      source = context.createMediaElementSource(media);
      // The analyser is a separate branch, so drawing never controls the sound.
      source.connect(context.destination);
      source.connect(analyser);
    } catch {
      // Unsupported media can still use the ambient visualizer.
    }
  };
  context.addEventListener("statechange", connect);

  return {
    analyser,
    resume: () => {
      connect();
      if (context.state !== "running" && context.state !== "closed") {
        void context
          .resume()
          .then(connect)
          .catch(() => {});
      }
    },
    dispose: () => {
      disposed = true;
      context.removeEventListener("statechange", connect);
      source?.disconnect();
      analyser.disconnect();
      if (context.state !== "closed") void context.close().catch(() => {});
    },
  };
}
