import { useMantineTheme } from "@mantine/core";
import { useMediaQuery } from "@mantine/hooks";
import { useSelector } from "react-redux";
import { RootState } from "@/domain/Store";
import { ItemDisplayType } from "@/domain/Types";
import { isAndroidApp } from "@/utils/browserCompat";

/** Keep the rows, heading and layout selector in agreement across orientations. */
export function useLibraryLayout() {
  const theme = useMantineTheme();
  const config = useSelector((state: RootState) => state.config);
  const isMobile = useMediaQuery(
    `(max-width: ${theme.breakpoints.sm})`,
    undefined,
    { getInitialValueInEffect: false },
  );
  const isPortrait = useMediaQuery("(orientation: portrait)", undefined, {
    getInitialValueInEffect: false,
  });
  const androidApp = isAndroidApp();
  return {
    androidApp,
    isMobile,
    canChooseLayout: !androidApp && !isPortrait,
    displayType:
      androidApp || isPortrait
        ? ItemDisplayType.List
        : isMobile
          ? config.mobileDisplayType
          : config.tvDisplayType,
  };
}
