import { ReactNode, RefObject, useRef, useState } from "react";
import { Box, Button, Text } from "@mantine/core";
import { useFullscreen, useMergedRef } from "@mantine/hooks";
import { IconMaximize, IconMinimize } from "@tabler/icons-react";
import { AudioVisualizer } from "./AudioVisualizer";

interface AudioPlayerProps {
  mediaRef: RefObject<HTMLMediaElement>;
  children: ReactNode;
}

type FullscreenContainer = HTMLDivElement & {
  webkitRequestFullscreen?: () => void | Promise<void>;
};

export function AudioPlayer({ mediaRef, children }: AudioPlayerProps) {
  const containerRef = useRef<FullscreenContainer>(null);
  const {
    ref: fullscreenRef,
    toggle,
    fullscreen,
  } = useFullscreen<HTMLDivElement>();
  const ref = useMergedRef(containerRef, fullscreenRef);
  const [fullscreenError, setFullscreenError] = useState(false);
  const fullscreenSupported = [
    "requestFullscreen",
    "webkitRequestFullscreen",
  ].some(
    (method) =>
      typeof Reflect.get(document.documentElement, method) === "function",
  );

  const toggleFullscreen = async () => {
    const container = containerRef.current;
    if (!container) return;
    setFullscreenError(false);
    try {
      if (fullscreen) await toggle();
      // Target this player even when the surrounding app is already full screen.
      else if (container.requestFullscreen) await container.requestFullscreen();
      else await container.webkitRequestFullscreen?.();
    } catch {
      setFullscreenError(true);
    }
  };

  return (
    <Box
      ref={ref}
      onKeyDown={(event) => {
        if (event.key === "Escape" && fullscreen) {
          event.stopPropagation();
          void toggleFullscreen();
        }
      }}
      sx={{
        display: "flex",
        flexDirection: "column",
        width: "100%",
        height: "100%",
        minHeight: 0,
        backgroundColor: "#000",
        "&:fullscreen": { width: "100vw", height: "100vh" },
        "&:-webkit-full-screen": { width: "100vw", height: "100vh" },
      }}
    >
      <Box
        sx={{ flex: 1, minHeight: 0, position: "relative", overflow: "hidden" }}
      >
        <AudioVisualizer mediaRef={mediaRef} />
        {fullscreenSupported && (
          <Button
            variant="default"
            size="sm"
            leftIcon={
              fullscreen ? (
                <IconMinimize size={18} />
              ) : (
                <IconMaximize size={18} />
              )
            }
            onClick={() => void toggleFullscreen()}
            sx={{
              position: "absolute",
              top: 12,
              right: 12,
              color: "#fff",
              backgroundColor: "rgba(0, 0, 0, 0.65)",
              "&:hover": { backgroundColor: "rgba(0, 0, 0, 0.85)" },
            }}
          >
            {fullscreen ? "Exit full screen" : "Full screen"}
          </Button>
        )}
        {fullscreenError && (
          <Text
            role="status"
            size="sm"
            p="xs"
            sx={{
              position: "absolute",
              bottom: 8,
              left: 8,
              color: "#fff",
              backgroundColor: "rgba(0, 0, 0, 0.85)",
            }}
          >
            Full screen could not start. Please try again.
          </Text>
        )}
      </Box>
      {children}
    </Box>
  );
}
