const STORAGE_KEY = "tvserver_auth";

// Store the pre-computed base64 token rather than raw credentials,
// so sessionStorage never contains the plaintext password.
let authToken: string | null = null;
let onUnauthorizedCallback: ((isRetry: boolean) => Promise<boolean>) | null = null;
let pendingLogin: Promise<boolean> | null = null;
const authSuccessCallbacks: (() => void)[] = [];

// Load token from sessionStorage on module init
try {
  const stored = sessionStorage.getItem(STORAGE_KEY);
  if (stored) {
    authToken = stored;
  }
} catch {
  // Ignore errors (e.g., SSR, sessionStorage unavailable)
}

function utf8ToBase64(str: string): string {
  const bytes = new TextEncoder().encode(str);
  let binary = "";
  for (const byte of bytes) {
    binary += String.fromCharCode(byte);
  }
  return btoa(binary);
}

export function setCredentials(username: string, password: string): void {
  authToken = utf8ToBase64(username + ":" + password);
  try {
    sessionStorage.setItem(STORAGE_KEY, authToken);
  } catch {
    // Ignore storage errors
  }
}

export function getAuthHeader(): string | null {
  if (!authToken) return null;
  return "Basic " + authToken;
}

export function getAuthQueryParam(): string | null {
  return authToken;
}

export function hasCredentials(): boolean {
  return !!authToken;
}

export function clearCredentials(): void {
  authToken = null;
  try {
    sessionStorage.removeItem(STORAGE_KEY);
  } catch {
    // Ignore storage errors
  }
}

export function registerUnauthorizedHandler(
  callback: (isRetry: boolean) => Promise<boolean>
): void {
  onUnauthorizedCallback = callback;
}

export function onAuthSuccess(callback: () => void): void {
  authSuccessCallbacks.push(callback);
}

export async function handleUnauthorized(): Promise<boolean> {
  if (!onUnauthorizedCallback) return false;

  // Concurrency guard: only one login modal at a time
  if (pendingLogin) return pendingLogin;

  const isRetry = hasCredentials();
  if (isRetry) {
    clearCredentials();
  }

  pendingLogin = onUnauthorizedCallback(isRetry).finally(() => {
    pendingLogin = null;
  });

  const result = await pendingLogin;
  if (result) {
    authSuccessCallbacks.forEach((cb) => cb());
  }
  return result;
}
