import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import { PlayRequest } from '@/domain/Messages';
import { videoPlay, videoSeek, videoTogglePause } from './SocketMiddleware';
import { ConnectionStatus } from '@/adaptors/SocketInterface';

interface VideoState {
  currentVideo?: PlayRequest;
  isPlaying: boolean;
  isConnected: boolean;
  connectionStatus: ConnectionStatus;
  reconnectAttempts: number;
  seekEvent?: number;
}

const initialState: VideoState = {
  currentVideo: undefined,
  isPlaying: false,
  isConnected: false,
  connectionStatus: 'disconnected',
  reconnectAttempts: 0,
  seekEvent: undefined
};

const videoSlice = createSlice({
  name: 'video',
  initialState,
  reducers: {
    setIsPlaying: (state, action: PayloadAction<boolean>) => {
      state.isPlaying = action.payload;
    },
    setIsConnected: (state, action: PayloadAction<boolean>) => {
      state.isConnected = action.payload;
    },
    setConnectionStatus: (state, action: PayloadAction<{ status: ConnectionStatus; attempts: number }>) => {
      state.connectionStatus = action.payload.status;
      state.reconnectAttempts = action.payload.attempts;
      state.isConnected = action.payload.status === 'connected';
    },
    clearSeekEvent: (state) => {
      state.seekEvent = undefined;
    },
    clearCurrentVideo: (state) => {
      state.currentVideo = undefined;
      state.isPlaying = false;
      state.seekEvent = undefined;
    }
  },
  extraReducers: (builder) => {
    builder
      .addCase(videoPlay, (state, action) => {
        state.currentVideo = action.payload;
        state.isPlaying = true;
      })
      .addCase(videoTogglePause, (state) => {
        state.isPlaying = !state.isPlaying;
      })
      .addCase(videoSeek, (state, action) => {
        state.seekEvent = action.payload;
      });
  }
});

export const { setIsConnected, setConnectionStatus, clearSeekEvent, clearCurrentVideo, setIsPlaying } = videoSlice.actions;
export default videoSlice.reducer;
