import {StatusCodes} from "../domain/Constants";
import {log_error} from "../services/Logger";
import { RestAdaptor } from "./Interfaces";
import { getAuthHeader, getAuthQueryParam, handleUnauthorized } from "./auth";


/**
 * Implementation of a Rest Adaptor using HTTP
 */
export class HTTPRestAdaptor implements RestAdaptor {
  private readonly host?: string;

  /**
   * Creates a new instance of the HTTPRestAdaptor with an optional host parameter
   * @param host An optional hostname to connect to
   */
  constructor(host?: string) {
    this.host = host;
  }

  /**
   * Returns the current host of the adaptor connection
   * @returns A string representing the current host, or null if no host is set
   */
  getHost = (): string | null => {
    return typeof this.host !== "undefined" ? this.host : null;
  }

  /**
   * Makes a GET request at the specified endpoint
   * @param path The endpoint to send the request to
   * @param options
   * @returns A Promise with the response data
   */
  get = async <T>(path: string, options?: RequestInit): Promise<T> => {
    const response = await this.fetchWithAuth(this.makeUrl(path), options);
    if (response.status !== StatusCodes.OK) {
      throw new Error(
        `GET ${path} returned ${response.status} ${response.statusText}`
      );
    }

    try {
      return await response.json();
    } catch (error) {
      if (typeof options === "undefined") {
        return this.get(path, {cache: "reload"})
      } else {
        log_error(error,`could not fetch ${path}`);
        throw error;
      }
    }
  }

  /**
   * Makes a POST request at the specified endpoint with the specified payload
   * @param path The endpoint to send the request to
   * @param payload The data to send with the request
   * @returns A Promise with the response from the server
   */
  post = async <T>(path: string, payload: T): Promise<Response> => {
    return this.send('POST', path, JSON.stringify(payload));
  }

  /**
   * Makes a PUT request at the specified endpoint with the specified payload
   * @param path The endpoint to send the request to
   * @param payload The data to send with the request
   * @returns A Promise with the response from the server
   */
  put = async <T>(path: string, payload: T): Promise<Response> => {
    return this.send('PUT', path, JSON.stringify(payload));
  }

  patch = async <T>(path: string, payload: T): Promise<Response> => {
    return this.send('PATCH', path, JSON.stringify(payload));
  }

  /**
   * Sends an HTTP request with the specified method, endpoint and payload
   * @param method The HTTP method to use for the request
   * @param path The endpoint to send the request to
   * @param payload The data to send with the request
   * @returns A Promise with the response from the server
   */
  send = async (method: string, path: string, payload: string): Promise<Response> => {
    const params: RequestInit = {
      method: method,
      body: payload,
      headers: {
        'Content-Type': 'application/json'
      }
    }

    return this.fetchWithAuth(this.makeUrl(path), params);
  }

  /**
   * Makes a DELETE request at the specified endpoint with the specified payload
   * @param path The endpoint to send the request to
   * @returns A Promise with the response from the server
   */
  delete = async(path: string): Promise<Response> => {
    return this.fetchWithAuth(this.makeUrl(path), { method: 'DELETE' });
  }

  /**
   * Constructs a URL to use for the request, based on the current host and the specified endpoint
   * @param path The endpoint to construct the URL for
   * @returns A string with the URL for the specified endpoint
   */
  makeUrl = (path: string): string => {
    if (typeof this.host !== "undefined") {
      const host = `http://${this.host}`;
      return `${host}/api/${path}`;
    }
    return `/api/${path}`;
  }

  getSocketHost = (host: string, protocol: string, path: string): string => {
    const useHost = typeof this.host === "undefined" ? host : this.host ;
    let url: string;
    switch (protocol) {
      case "http:":
        url = `ws://${useHost}/${path}`;
        break;
      case "https:":
        url = `wss://${useHost}/${path}`;
        break;
      default:
        console.log(`Unknown protocol: ${protocol} - ${path}`);
        url = `ws://${useHost}/${path}`;
        break;
    }
    // Browser WebSocket API cannot set custom headers, so credentials are
    // passed as a query parameter. The base64 value is not encryption — it is
    // visible in server logs and browser history. Acceptable trade-off for this
    // home server; a production system would use a short-lived token exchange.
    const authParam = getAuthQueryParam();
    if (authParam) {
      url += (url.includes('?') ? '&' : '?') + `auth=${encodeURIComponent(authParam)}`;
    }
    return url;
  }

  /**
   * Wraps fetch with auth header injection and 401 handling.
   * If a 401 is received, triggers the login flow and retries on success.
   */
  private fetchWithAuth = async (url: string, init?: RequestInit, authAttempts = 0): Promise<Response> => {
    const response = await fetch(url, this.withAuthHeaders(init));

    if (response.status === StatusCodes.UNAUTHORIZED && authAttempts < 3) {
      const loggedIn = await handleUnauthorized();
      if (loggedIn) {
        return this.fetchWithAuth(url, init, authAttempts + 1);
      }
    }

    return response;
  }

  private withAuthHeaders = (init?: RequestInit): RequestInit => {
    const authHeader = getAuthHeader();
    if (!authHeader) return init || {};

    const headers = new Headers(init?.headers);
    headers.set("Authorization", authHeader);
    return { ...init, headers };
  }
}
