export interface AudioReaction {
  waveform: Float32Array;
  spectrum: Uint8Array;
  bass: number;
  treble: number;
  energy: number;
  pulse: number;
  beat: boolean;
}

// Both Web Audio and Android's session-scoped output analyser supply this shape.
export interface AudioAnalyser {
  readonly fftSize: number;
  readonly context: { readonly sampleRate: number };
  getByteFrequencyData: (buffer: Uint8Array) => void;
  getByteTimeDomainData: (buffer: Uint8Array) => void;
}

const clamp = (value: number) => Math.max(0, Math.min(1, value));

// Fast attack, slower release, with timings independent of the drawing rate.
function follow(current: number, target: number, elapsed: number) {
  return (
    current +
    (target - current) *
      (1 - Math.exp(-elapsed / (target > current ? 0.018 : 0.18)))
  );
}

export function createAudioReactivity() {
  const samples = new Uint8Array(1024);
  const reaction: AudioReaction = {
    waveform: new Float32Array(1024),
    spectrum: new Uint8Array(512),
    bass: 0,
    treble: 0,
    energy: 0,
    pulse: 0,
    beat: false,
  };
  let averageBass = 0;
  let averageVolume = 0;
  let previousBass = 0;
  let previousVolume = 0;
  let peakVolume = 0.08;
  let sinceBeat = 1;

  // The buffers and returned reading are reused rather than allocated per frame.
  return (elapsed: number, analyser?: AudioAnalyser): AudioReaction => {
    const dt = Math.min(0.1, Math.max(0, elapsed));
    let bass = 0;
    let treble = 0;
    let volume = 0;
    if (analyser) {
      analyser.getByteFrequencyData(reaction.spectrum);
      analyser.getByteTimeDomainData(samples);
      const binWidth = analyser.context.sampleRate / analyser.fftSize;
      const band = (from: number, to: number) => {
        const start = Math.max(1, Math.floor(from / binWidth));
        const end = Math.min(
          reaction.spectrum.length,
          Math.ceil(to / binWidth),
        );
        let sum = 0;
        for (let bin = start; bin < end; bin++)
          sum += reaction.spectrum[bin] / 255;
        return sum / Math.max(1, end - start);
      };
      bass = band(40, 180);
      treble = band(2500, 10000);
      for (const sample of samples) volume += ((sample - 128) / 128) ** 2;
      volume = Math.sqrt(volume / samples.length);
      peakVolume = Math.max(volume, peakVolume * Math.exp(-dt * 0.25), 0.04);
      const gain = Math.min(5, 0.55 / peakVolume);
      for (let i = 0; i < samples.length; i++) {
        reaction.waveform[i] = Math.max(
          -1,
          Math.min(1, ((samples[i] - 128) / 128) * gain),
        );
      }
    } else {
      reaction.spectrum.fill(0);
      reaction.waveform.fill(0);
    }

    sinceBeat += dt;
    // Compare with the recent level and require a rising edge. Sustained bass
    // stays animated without repeatedly masquerading as a new drum hit.
    const bassOnset =
      bass > averageBass * 1.18 + 0.035 && bass - previousBass > 0.025;
    const volumeOnset =
      volume > averageVolume * 1.5 + 0.008 && volume - previousVolume > 0.012;
    reaction.beat =
      volume > 0.012 && sinceBeat >= 0.22 && (bassOnset || volumeOnset);
    if (reaction.beat) sinceBeat = 0;
    reaction.pulse = reaction.beat ? 1 : reaction.pulse * Math.exp(-dt * 5.5);
    reaction.bass = follow(reaction.bass, bass, dt);
    reaction.treble = follow(reaction.treble, treble, dt);
    reaction.energy = follow(
      reaction.energy,
      clamp(volume / Math.max(0.06, peakVolume * 0.8)),
      dt,
    );
    const averaging = 1 - Math.exp(-dt / 0.85);
    averageBass += (bass - averageBass) * averaging;
    averageVolume += (volume - averageVolume) * averaging;
    previousBass = bass;
    previousVolume = volume;
    return reaction;
  };
}
