import { FC } from "react";
import { Affix, Box, Group } from "@mantine/core";
import { VideoPlayer } from "@/services/Player";
import { BackButton } from "../Video/BackButton";
import { DisplaySelector } from "../Video/DisplaySelector";
import VideoSelection from "../Video/VideoSelection";
import { VideoDetails } from "../../domain/Messages";
import { isVideoPlayable } from "@/domain/VideoProcessingState";

type PickerProps = {
  videoPlayer: VideoPlayer;
  togglePause?: () => void;
  visible: boolean;
};

export const Picker: FC<PickerProps> = ({
  videoPlayer,
  togglePause,
  visible,
}) => {
  const showVideoDetails = (video: VideoDetails) => {
    console.log(`video: ${video.video}`);
    if (isVideoPlayable(video)) {
      videoPlayer.playVideo(video);
    }
  };

  return (
    <Affix
      className="library-picker"
      // Keep the existing HTML audio transport and Hide library button reachable.
      position={{ top: 24, left: 16, right: 16, bottom: 80 }}
      sx={{
        transform: `translateY(${visible ? "0" : "-120%"})`,
        opacity: visible ? 1 : 0,
        pointerEvents: visible ? "auto" : "none",
        transition: "transform 0.25s ease-out, opacity 0.2s",
        maxWidth: 1180,
        margin: "0 auto",
      }}
    >
      <Box
        sx={{
          height: "100%",
          overflowY: "auto",
          background: "#0A0E14F5",
          border: "1px solid #293544",
          borderRadius: 24,
          padding: 24,
        }}
      >
        <Group position="apart" mb="lg" sx={{ "&:empty": { display: "none" } }}>
          <BackButton size="sm" />
          <DisplaySelector size="xs" />
        </Group>
        <VideoSelection
          videoPlayer={videoPlayer}
          isActive={visible}
          showVideoDetails={showVideoDetails}
        />
      </Box>
    </Affix>
  );
};
