import { useState } from "react";
import { TextInput, PasswordInput, Button, Stack, Text } from "@mantine/core";
import { modals } from "@mantine/modals";
import { setCredentials } from "@/adaptors/auth";

interface LoginFormProps {
  modalId: string;
  isRetry: boolean;
  onSuccess: () => void;
}

function LoginForm({ modalId, isRetry, onSuccess }: LoginFormProps) {
  const [user, setUser] = useState("");
  const [pass, setPass] = useState("");

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (user && pass) {
      setCredentials(user, pass);
      modals.close(modalId);
      onSuccess();
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <Stack spacing="sm">
        {isRetry && (
          <Text color="red" size="sm">
            Invalid username or password
          </Text>
        )}
        <TextInput
          label="Username"
          placeholder="Username"
          value={user}
          onChange={(e) => setUser(e.currentTarget.value)}
          data-autofocus
        />
        <PasswordInput
          label="Password"
          placeholder="Password"
          value={pass}
          onChange={(e) => setPass(e.currentTarget.value)}
        />
        <Button type="submit" fullWidth disabled={!user || !pass}>
          Login
        </Button>
      </Stack>
    </form>
  );
}

export function showLoginModal(isRetry: boolean = false): Promise<boolean> {
  return new Promise<boolean>((resolve) => {
    let resolved = false;

    const modalId = "login-modal";

    modals.open({
      modalId,
      title: "Authentication Required",
      closeOnClickOutside: false,
      closeOnEscape: false,
      withCloseButton: true,
      onClose: () => {
        if (!resolved) {
          resolved = true;
          resolve(false);
        }
      },
      children: (
        <LoginForm
          modalId={modalId}
          isRetry={isRetry}
          onSuccess={() => {
            resolved = true;
            resolve(true);
          }}
        />
      ),
    });
  });
}
