import type { VideoDetails } from './Messages';

export enum VideoProcessingState {
  Ready = 'Ready',
  NewFile = 'NewFile',
  ZeroFileSize = 'ZeroFileSize',
  NoVideoSize = 'NoVideoSize',
  NeedThumbnail = 'NeedThumbnail',
  NeedVideoMetaData = 'NeedVideoMetaData',
  NeedDescription = 'NeedDescription',
  Exception = 'Exception',
}

export type SerializedVideoState = VideoProcessingState | number;

const videoProcessingStates = new Set<string>(
  Object.values(VideoProcessingState),
);

const numericStates: Record<number, VideoProcessingState> = {
  0: VideoProcessingState.Ready,
  1: VideoProcessingState.NewFile,
  2: VideoProcessingState.ZeroFileSize,
  3: VideoProcessingState.NoVideoSize,
  4: VideoProcessingState.NeedThumbnail,
  5: VideoProcessingState.NeedVideoMetaData,
  6: VideoProcessingState.NeedDescription,
  10: VideoProcessingState.Exception,
};

const labels: Partial<Record<VideoProcessingState, string>> = {
  [VideoProcessingState.NewFile]: 'Processing video',
  [VideoProcessingState.ZeroFileSize]: 'File is empty',
  [VideoProcessingState.NoVideoSize]: 'Video dimensions unavailable',
  [VideoProcessingState.NeedThumbnail]: 'Thumbnail unavailable',
  [VideoProcessingState.NeedVideoMetaData]: 'Metadata unavailable',
  [VideoProcessingState.NeedDescription]: 'Description unavailable',
  [VideoProcessingState.Exception]: 'Processing failed',
};

export const normalizeVideoProcessingState = (
  state: SerializedVideoState,
): VideoProcessingState | undefined => {
  if (typeof state === 'number') {
    return numericStates[state];
  }

  return videoProcessingStates.has(state) ? state : undefined;
};

export const getVideoProcessingStatus = (
  state: SerializedVideoState,
): string | undefined => {
  const normalized = normalizeVideoProcessingState(state);
  if (normalized === VideoProcessingState.Ready) {
    return undefined;
  }

  return (normalized && labels[normalized]) ?? 'Processing failed';
};

export const isAudioOnly = (video: VideoDetails): boolean =>
  video.metadata.duration > 0 &&
  video.metadata.width === 0 &&
  video.metadata.height === 0 &&
  video.metadata.audioTracks > 0;

const hasUsableMetadata = (video: VideoDetails): boolean =>
  video.metadata.duration > 0 &&
  ((video.metadata.width > 0 && video.metadata.height > 0) ||
    isAudioOnly(video));

export const isVideoPlayable = (video: VideoDetails): boolean => {
  const state = normalizeVideoProcessingState(video.state);

  return (
    (state === VideoProcessingState.Ready ||
      state === VideoProcessingState.NeedThumbnail) &&
    hasUsableMetadata(video)
  );
};
