import { getAuthQueryParam } from "@/adaptors/auth";
import { RestAdaptor } from "@/adaptors/Interfaces";
import { PlayRequest, VideoDetails } from "@/domain/Messages";
import { isTauri } from "@/utils/browserCompat";

export function localPlayRequest(
  video: VideoDetails,
  host: RestAdaptor,
): PlayRequest {
  const path = [...video.collection.split("/").filter(Boolean), video.video]
    .map(encodeURIComponent)
    .join("/");
  const server = host.getHost();
  const origin = server
    ? server.includes("://")
      ? server
      : `${window.location.protocol}//${server}`
    : window.location.origin;
  // Native library URLs are filesystem paths. Preserve them for convertFileSrc,
  // including literal spaces, # and other characters which URL parsing changes.
  const url = isTauri() && video.url
    ? video.url
    : new URL(video.url || `/api/stream/${path}`, origin).href;

  return {
    remoteAddress: "",
    url,
    collection: video.collection,
    video: video.video,
    videoId: video.checksum,
    width: video.metadata.width,
    height: video.metadata.height,
    aspectWidth: video.metadata.aspectWidth,
    aspectHeight: video.metadata.aspectHeight,
    metadata: video.metadata,
  };
}

// Media elements cannot use the REST adaptor's Authorization header. The
// server already accepts this query parameter for browser connections.
export function authenticatedMediaUrl(source: string): string {
  const token = getAuthQueryParam();
  const url = new URL(source, window.location.href);
  if (
    !token ||
    url.origin !== window.location.origin ||
    !url.pathname.startsWith("/api/")
  ) {
    return source;
  }
  url.searchParams.set("auth", token);
  return url.href;
}

export function subtitleUrl(source: string, language: string): string {
  const url = new URL(source, window.location.href);
  url.pathname =
    url.pathname.replace(/\.[^/.]*$/, "") + `-${language.toUpperCase()}.vtt`;
  return url.href;
}
