import {
  IconDownload,
  IconPlayerPlay,
  IconSearch,
  IconStack2,
} from "@tabler/icons-react";
import { Box, Text, UnstyledButton } from "@mantine/core";
import { useSelector } from "react-redux";
import { RootState } from "@/domain/Store";

type SpeedDialerProps = {
  showTasks: () => void;
  showSearch: () => void;
  showCurrentVideo: () => void;
  showLibrary?: () => void;
  active?: "library" | "search" | "tasks" | "playing";
};

/** One compact navigation dock keeps the library clear on phones and desktops. */
export const SpeedDialer = (props: SpeedDialerProps) => {
  const currentTasks =
    useSelector((state: RootState) => state.remote.lastCurrentTasks) ?? [];
  const items = [
    {
      id: "library",
      label: "Library",
      icon: IconStack2,
      action: props.showLibrary,
    },
    {
      id: "search",
      label: "Search",
      icon: IconSearch,
      action: props.showSearch,
    },
    ...(currentTasks.length
      ? [
          {
            id: "tasks",
            label: "Running tasks",
            title: "Tasks",
            icon: IconDownload,
            action: props.showTasks,
          },
        ]
      : []),
    {
      id: "playing",
      label: "Currently playing",
      title: "Playing",
      icon: IconPlayerPlay,
      action: props.showCurrentVideo,
    },
  ];
  return (
    <Box
      component="nav"
      aria-label="Main navigation"
      className="navigation-dock"
    >
      {items.map(({ id, label, title, icon: Icon, action }) => (
        <UnstyledButton
          key={id}
          onClick={action}
          aria-label={label}
          aria-current={props.active === id ? "page" : undefined}
          className="navigation-item"
        >
          <Icon size={21} stroke={1.7} />
          <Text component="span" size="xs" weight={500}>
            {title ?? label}
          </Text>
        </UnstyledButton>
      ))}
    </Box>
  );
};
