import { Badge, Center, Stack, Text } from "@mantine/core";
import { IconAlertTriangle, IconMusic } from "@tabler/icons-react";
import { FC } from "react";
import { getVideoProcessingStatus } from "@/domain/VideoProcessingState";
import type { SerializedVideoState } from "@/domain/VideoProcessingState";

interface StatusProps {
  state: SerializedVideoState;
}

interface PlaceholderProps extends StatusProps {
  height: number;
  audioOnly?: boolean;
}

export const VideoProcessingBadge: FC<StatusProps> = ({ state }) => {
  const message = getVideoProcessingStatus(state);
  return message ? (
    <Badge color="yellow" role="status" aria-label={message}>
      {message}
    </Badge>
  ) : null;
};

export const VideoThumbnailPlaceholder: FC<PlaceholderProps> = ({
  state,
  height,
  audioOnly = false,
}) => {
  const message = audioOnly
    ? "Audio file"
    : (getVideoProcessingStatus(state) ?? "Thumbnail unavailable");
  const Icon = audioOnly ? IconMusic : IconAlertTriangle;

  return (
    <Center h={height} bg="dark.5" role="img" aria-label={message}>
      <Stack align="center" spacing="xs">
        <Icon aria-hidden color="#8CE4CD" size={audioOnly ? 64 : 32} />
        <Text color="dimmed">{message}</Text>
      </Stack>
    </Center>
  );
};
