import { FC } from "react";
import { Group, Text, Box } from "@mantine/core";
import { useSelector } from "react-redux";
import { Player } from "../../services/Player";
import { BackButton } from "./BackButton";
import { DisplaySelector } from "./DisplaySelector";
import VideoSelection from "./VideoSelection";
import { VideoDetails } from "@/domain/Messages";
import { RootState } from "@/domain/Store";
import { getCleanName, getCollectionsAndVideos } from "@/domain/Utils";
import { ItemDisplayType } from "@/domain/Types";
import { useLibraryLayout } from "./useLibraryLayout";

export interface IVideoConfig {
  videoPlayer: Player;
  isActive: boolean;
  showVideoDetails: (video: VideoDetails) => void;
}

const VideoTab: FC<IVideoConfig> = ({
  videoPlayer,
  isActive,
  showVideoDetails,
}) => {
  const { displayType, canChooseLayout } = useLibraryLayout();
  const isList = displayType === ItemDisplayType.List;
  const { activeSeries, currentSeason } = useSelector(
    (state: RootState) => state.series,
  );
  const title = currentSeason
    ? getCleanName(currentSeason)
    : activeSeries?.collection
      ? getCleanName(activeSeries.collection)
      : "Your library";
  const contents = activeSeries
    ? getCollectionsAndVideos(activeSeries, currentSeason)
    : undefined;
  const count = contents
    ? contents.child_collections.length + contents.videos.length
    : 0;
  return (
    <>
      {isList ? (
        canChooseLayout ? (
          <Group position="apart" mb="md">
            <BackButton size="sm" />
            <DisplaySelector size="xs" />
          </Group>
        ) : (
          <BackButton size="sm" />
        )
      ) : (
        <>
          <BackButton size="sm" />
          <Group position="apart" align="flex-end" className="library-heading">
            <Box sx={{ minWidth: 0, flex: 1 }}>
              <Text color="dimmed" size="xs" weight={500} mb={8}>
                LIBRARY
              </Text>
              <h1 className="library-title">{title}</h1>
              <Text size="sm" color="dimmed">
                {count
                  ? `${count} ${count === 1 ? "item" : "items"}`
                  : "Videos and audio, all in one place"}
              </Text>
            </Box>
            {canChooseLayout && <DisplaySelector size="xs" />}
          </Group>
        </>
      )}
      <VideoSelection
        videoPlayer={videoPlayer}
        isActive={isActive}
        showVideoDetails={showVideoDetails}
      />
    </>
  );
};
export default VideoTab;
