import { VideoDetails } from "@/domain/Messages";
import { GetVideoName } from "@/domain/Utils";
import { Group, List, Stack, Text } from "@mantine/core";
import { IconChevronRight } from "@tabler/icons-react";
import { FC } from "react";
import { isAudioOnly } from "@/domain/VideoProcessingState";
import { secondsToHMSString } from "@/services/helpers";
import { VideoProcessingBadge } from "./VideoProcessingStatus";
import { LibraryThumbnail } from "./LibraryThumbnail";

interface IVideoItem {
  video: VideoDetails;
  showVideoDetails?: (video: VideoDetails) => void;
}

export const VideoItem: FC<IVideoItem> = ({ video, showVideoDetails }) => {
  const displayName = GetVideoName(video);
  const showDialog = () => showVideoDetails?.(video);
  return (
    <List.Item className="library-row" onClick={showDialog}>
      <Group
        noWrap
        spacing="md"
        role="button"
        tabIndex={0}
        aria-label={`Details for ${displayName}`}
        onKeyDown={(event) => {
          if (event.key === "Enter" || event.key === " ") {
            event.preventDefault();
            showDialog();
          }
        }}
      >
        <LibraryThumbnail
          thumbnails={video.thumbnail}
          name={displayName}
          audioOnly={isAudioOnly(video)}
        />
        <Stack spacing={4} sx={{ flex: 1, minWidth: 0 }}>
          <Text weight={500} lineClamp={2} sx={{ overflowWrap: "anywhere" }}>
            {displayName}
          </Text>
          <Text size="xs" color="dimmed">
            {secondsToHMSString(video.metadata.duration)}
          </Text>
          <VideoProcessingBadge state={video.state} />
        </Stack>
        <IconChevronRight size={18} color="#B8C2CF" />
      </Group>
    </List.Item>
  );
};
