import { AppDispatch } from "@/domain/Store";
import {
  setTvDisplayType,
  setMobileDisplayType,
} from "@/domain/Store/ConfigReducer";
import { ItemDisplayType } from "@/domain/Types";
import { SegmentedControl } from "@mantine/core";
import { FC } from "react";
import { useDispatch } from "react-redux";

import { useLibraryLayout } from "./useLibraryLayout";

interface IDisplaySelector {
  size?: "xs" | "sm" | "md" | "lg" | "xl";
}

export const DisplaySelector: FC<IDisplaySelector> = ({ size = "xl" }) => {
  const dispatch: AppDispatch = useDispatch();
  const { displayType, isMobile, canChooseLayout } = useLibraryLayout();

  const setValue = (value: string) => {
    dispatch(
      (isMobile ? setMobileDisplayType : setTvDisplayType)(
        parseInt(value) as ItemDisplayType,
      ),
    );
  };

  if (!canChooseLayout) return null;

  return (
    <SegmentedControl
      size={size}
      aria-label="Library layout"
      value={displayType.toString()}
      onChange={setValue}
      data={[
        { label: "Carousel", value: ItemDisplayType.Carousel.toString() },
        { label: "Grid", value: ItemDisplayType.Grid.toString() },
        { label: "List", value: ItemDisplayType.List.toString() },
      ]}
    />
  );
};
