import { useRef, useState } from "react";
import { AspectRatio, Box, Button, Group, Paper, Stack, Text } from "@mantine/core";
import { useDebouncedState } from "@mantine/hooks";
import { useDispatch, useSelector } from "react-redux";
import { RootState } from "@/domain/Store";
import { RestAdaptor } from "@/adaptors/Interfaces";
import { VideoPlayer } from "@/services/Player";
import { useTabVisibility } from "@/services/helpers";
import { Controls } from "./Controls";
import { AudioPlaybackControls } from "./AudioPlaybackControls";
import { AppAppearance } from '../Base/Appearance';
import { Picker } from "./Picker";
import { PlayState, PlayerHandlers } from './Player';
import Player from './RemotePlayer';
import { videoTogglePause, socketRetryConnect } from "@/domain/Store/SocketMiddleware";
import { clearCurrentVideo } from "@/domain/Store/VideoReducer";

type VideoControlProps = {
  host: RestAdaptor;
}

const Viewer = (props: VideoControlProps) => {
  const dispatch = useDispatch();
  const videoControlRef = useRef<PlayerHandlers | null>(null);
  const [debouncedShowControls, setDebouncedShowControls] = useDebouncedState(true, 200);
  const [wasPlaying, setWasPlaying] = useState(false);
  const [showAudioPicker, setShowAudioPicker] = useState(false);
  const { currentVideo, isPlaying } = useSelector((state: RootState) => state.video);
  const audioOnly = currentVideo?.width === 0 && currentVideo?.height === 0;
  const videoPlayer = new VideoPlayer(props.host, "");

  const seek = (interval: number) => {
    if (videoControlRef.current !== null) {
      videoControlRef.current.seek(interval);
    }
  }

  useTabVisibility((newState: string) => {
    switch (newState) {
      case "visible":
        dispatch(socketRetryConnect()); // Use the retry action instead of reconnect
        if (wasPlaying) {
          setWasPlaying(false);
          videoControlRef.current?.pause();
        }
        break;
      case "hidden":
        if (videoControlRef.current?.isPlaying()) {
          setWasPlaying(true);
          videoControlRef.current?.pause(); 
        }
    }
  });

  const showControls = (show: boolean) => {
    setDebouncedShowControls(show);
  }

  const onStateChange = (newState: PlayState) => {
    console.log(`state change: ${newState}`);
    switch (newState) {
      case PlayState.STARTED:
        console.log("onStateChange: started");
        showControls(audioOnly);
        break;
      case PlayState.PAUSED:     
      case PlayState.STOPPED:
        console.log("onStateChange: stopped/paused");
        if (!debouncedShowControls) {
          console.log("hiding video");
          //showControls(true);
        }
    }
  }

  let player = (<></>);
  const stopAudio = () => {
    videoControlRef.current?.stop();
    dispatch(clearCurrentVideo());
    setWasPlaying(false);
    setShowAudioPicker(false);
    showControls(true);
  };
  const osd = (
    !audioOnly && !debouncedShowControls &&
    <Controls 
      seek={seek} 
      isPlaying={videoControlRef.current?.isPlaying}
      currentlyPlaying={isPlaying}
      togglePause={() => {
        dispatch(videoTogglePause());
      }}
      quit={() => showControls(true)}
      playerRef={videoControlRef}
    />
  )
 
  if (typeof currentVideo !== "undefined") {
    player = audioOnly ? (
      <Paper
        role="region"
        aria-label="Audio player"
        withBorder
        p="sm"
        sx={{
          position: 'absolute',
          top: 0,
          bottom: 0,
          left: 0,
          right: 0,
          zIndex: 200,
          backgroundColor: '#000',
          color: '#fff',
        }}
      >
        <Stack spacing="xs" h="100%">
          <Text size="sm" lineClamp={1}>
            {currentVideo.video}
          </Text>
          <Box sx={{ flex: 1, minHeight: 0 }}>
            <Player
              currentVideo={currentVideo}
              ref={videoControlRef}
              audioOnly
              onStateChange={onStateChange}
            />
          </Box>
          <Group position="center" spacing="xs">
            <AudioPlaybackControls
              isPlaying={isPlaying}
              togglePause={() => dispatch(videoTogglePause())}
              stop={stopAudio}
            />
            <Button variant="light" onClick={() => setShowAudioPicker((show) => !show)}>
              {showAudioPicker ? 'Hide library' : 'Browse library'}
            </Button>
          </Group>
        </Stack>
      </Paper>
    ) : (
      <>
        <AspectRatio 
          ratio={currentVideo.aspectWidth / currentVideo.aspectHeight}
          sx={{ width: '100%', height: '100%' }}
        >
          <Player 
            currentVideo={currentVideo} 
            ref={videoControlRef} 
            onStateChange={onStateChange}
          />
        </AspectRatio>
        { osd }
      </>
    )
  };

  // Always render the Picker but control visibility with the prop
  const controls = (
    <Picker 
      videoPlayer={videoPlayer} 
      togglePause={() => {
        dispatch(videoTogglePause());
      }}
      visible={audioOnly ? showAudioPicker : debouncedShowControls}
    />
  );

  return (
    <Box sx={{ backgroundColor: '#000000', position: 'fixed', top: 0, left: 0, right: 0, bottom: 0 }}>
      {player}
      <AppAppearance>{controls}</AppAppearance>
    </Box>
  );
};

export default Viewer;
