import { FC, ReactNode, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import { invoke } from "@tauri-apps/api/core";
import {
  ActionIcon,
  Box,
  Loader,
  Menu,
  Stack,
  Text,
  UnstyledButton,
} from "@mantine/core";
import {
  IconChevronRight,
  IconDotsVertical,
  IconDownload,
  IconInfoCircle,
  IconRefresh,
  IconShare,
  IconTrash,
} from "@tabler/icons-react";
import { AppDispatch, RootState } from "@/domain/Store";
import {
  fetchSeriesDetails,
  setCurrentSeason,
} from "@/domain/Store/SeriesReducer";
import { VideoDetails } from "@/domain/Messages";
import {
  getCleanName,
  getCollectionsAndVideos,
  GetVideoName,
} from "@/domain/Utils";
import { isVideoPlayable, isAudioOnly } from "@/domain/VideoProcessingState";
import { Player } from "@/services/Player";
import { secondsToHMSString } from "@/services/helpers";
import { askQuestion, showErrorAlert } from "../Base/Alert";
import { ConvertModal, VideoMetadataModal } from "./Modals";
import { VideoProcessingBadge } from "./VideoProcessingStatus";
import { LibraryThumbnail } from "./LibraryThumbnail";

const Row: FC<{ children: ReactNode }> = ({ children }) => (
  <Box
    component="li"
    sx={(theme) => ({
      display: "flex",
      alignItems: "center",
      gap: 4,
      padding: "12px",
      borderRadius: 16,
      backgroundColor: theme.colors.dark[6],
      marginBottom: 8,
      "&:hover": { backgroundColor: theme.colors.dark[5] },
      borderBottom: `1px solid ${theme.colorScheme === "dark" ? theme.colors.dark[4] : theme.colors.gray[2]}`,
    })}
  >
    {children}
  </Box>
);

/** Android has one library layout in both orientations, with native file actions. */
export const AndroidVideoList: FC<{ videoPlayer: Player }> = ({
  videoPlayer: player,
}) => {
  const dispatch: AppDispatch = useDispatch();
  const activeSeries = useSelector(
    (state: RootState) => state.series.activeSeries,
  );
  const currentSeason = useSelector(
    (state: RootState) => state.series.currentSeason,
  );
  const [information, setInformation] = useState<VideoDetails>();
  const [conversion, setConversion] = useState<VideoDetails>();
  const [busy, setBusy] = useState<string>();

  if (!activeSeries)
    return <Text>Nothing to watch - download some videos</Text>;
  const { child_collections, videos } = getCollectionsAndVideos(
    activeSeries,
    currentSeason,
  );

  const run = async (id: string, action: () => Promise<unknown>) => {
    setBusy(id);
    try {
      await action();
    } catch (error) {
      showErrorAlert(error instanceof Error ? error.message : String(error));
    } finally {
      setBusy(undefined);
    }
  };

  const remove = (id: string, name: string, collection = false) => {
    askQuestion(
      collection
        ? `Delete all videos in "${name}"?`
        : `Delete video "${name}"?`,
      () => {
        void run(id, async () => {
          await invoke("delete_video", { videoId: id });
          await dispatch(fetchSeriesDetails(activeSeries.collection)).unwrap();
        });
      },
    );
  };

  const actions = (id: string, name: string, items: ReactNode) => (
    <Menu position="bottom-end" withinPortal width={220}>
      <Menu.Target>
        <ActionIcon
          aria-label={`More actions for ${name}`}
          size={44}
          variant="subtle"
          disabled={busy !== undefined}
        >
          {busy === id ? <Loader size={18} /> : <IconDotsVertical size={22} />}
        </ActionIcon>
      </Menu.Target>
      <Menu.Dropdown>{items}</Menu.Dropdown>
    </Menu>
  );

  return (
    <>
      <Box
        component="ul"
        aria-label="Video library"
        m={0}
        sx={{ listStyle: "none", padding: 0 }}
      >
        {child_collections.map((child) => {
          const name = child.collection
            ? getCleanName(child.collection)
            : "Others";
          const id = activeSeries.collection
            ? `${activeSeries.collection}/${child.collection}`
            : child.collection;
          return (
            <Row key={`collection:${id}`}>
              <UnstyledButton
                aria-label={`Open ${name}`}
                sx={{
                  display: "flex",
                  alignItems: "center",
                  gap: 12,
                  flex: 1,
                  minWidth: 0,
                }}
                onClick={() => {
                  if (activeSeries.collection === "")
                    dispatch(fetchSeriesDetails(child.collection));
                  else dispatch(setCurrentSeason(child.collection));
                }}
              >
                <LibraryThumbnail
                  thumbnails={child.thumbnail}
                  name={name}
                  folder
                />
                <Text
                  component="span"
                  weight={500}
                  lineClamp={2}
                  sx={{ flex: 1, overflowWrap: "anywhere" }}
                >
                  {name}
                </Text>
                <IconChevronRight
                  size={18}
                  aria-hidden
                  style={{ flexShrink: 0 }}
                />
              </UnstyledButton>
              {actions(
                id,
                name,
                <>
                  <Menu.Item
                    icon={<IconShare size={18} />}
                    onClick={() =>
                      void run(id, () =>
                        invoke("android_video_share", { videoId: id }),
                      )
                    }
                  >
                    Share
                  </Menu.Item>
                  <Menu.Divider />
                  <Menu.Item
                    color="red"
                    icon={<IconTrash size={18} />}
                    onClick={() => remove(id, name, true)}
                  >
                    Delete
                  </Menu.Item>
                </>,
              )}
            </Row>
          );
        })}
        {videos.map((video) => {
          const name = GetVideoName(video);
          return (
            <Row key={video.checksum}>
              <UnstyledButton
                aria-label={`Play ${name}`}
                disabled={!isVideoPlayable(video)}
                sx={{
                  display: "flex",
                  alignItems: "center",
                  gap: 12,
                  flex: 1,
                  minWidth: 0,
                }}
                onClick={() => player.playVideo(video)}
              >
                <LibraryThumbnail
                  thumbnails={video.thumbnail}
                  name={name}
                  audioOnly={isAudioOnly(video)}
                />
                <Stack spacing={4} sx={{ minWidth: 0, flex: 1 }}>
                  <Text
                    component="span"
                    weight={500}
                    lineClamp={2}
                    sx={{ overflowWrap: "anywhere" }}
                  >
                    {name}
                  </Text>
                  <Text component="span" size="xs" color="dimmed">
                    {secondsToHMSString(video.metadata.duration)}
                  </Text>
                  <VideoProcessingBadge state={video.state} />
                </Stack>
              </UnstyledButton>
              {actions(
                video.checksum,
                name,
                <>
                  <Menu.Item
                    icon={<IconInfoCircle size={18} />}
                    onClick={() => setInformation(video)}
                  >
                    Video information
                  </Menu.Item>
                  <Menu.Item
                    icon={<IconRefresh size={18} />}
                    disabled={!isVideoPlayable(video)}
                    onClick={() => setConversion(video)}
                  >
                    Convert
                  </Menu.Item>
                  <Menu.Item
                    icon={<IconDownload size={18} />}
                    onClick={() =>
                      void run(video.checksum, () =>
                        invoke("android_video_export", {
                          videoId: video.checksum,
                        }),
                      )
                    }
                  >
                    Download
                  </Menu.Item>
                  <Menu.Item
                    icon={<IconShare size={18} />}
                    onClick={() =>
                      void run(video.checksum, () =>
                        invoke("android_video_share", {
                          videoId: video.checksum,
                        }),
                      )
                    }
                  >
                    Share
                  </Menu.Item>
                  <Menu.Divider />
                  <Menu.Item
                    color="red"
                    icon={<IconTrash size={18} />}
                    onClick={() => remove(video.checksum, video.video)}
                  >
                    Delete
                  </Menu.Item>
                </>,
              )}
            </Row>
          );
        })}
      </Box>
      {information && (
        <VideoMetadataModal
          video={information.video}
          metadata={information.metadata}
          onClose={() => setInformation(undefined)}
        />
      )}
      {conversion && (
        <ConvertModal
          video={conversion.video}
          videoId={conversion.checksum}
          player={player}
          onClose={() => setConversion(undefined)}
        />
      )}
    </>
  );
};
