import { Box, Stack, Table, Text, Title } from "@mantine/core";

import type { AudioTrack } from "@/domain/Messages";

interface AudioStreamDetailsProps {
  tracks?: readonly AudioTrack[];
}

const EMPTY_VALUE = "—";

function displayValue(...values: Array<string | undefined>): string {
  return values.find((value) => value?.trim())?.trim() ?? EMPTY_VALUE;
}

export function AudioStreamDetails({
  tracks,
}: AudioStreamDetailsProps): JSX.Element | null {
  if (!tracks?.length) {
    return null;
  }

  return (
    <Stack spacing="xs" mt="sm">
      <Title order={5}>Audio Streams</Title>
      <Box sx={{ overflowX: "auto" }}>
        <Table aria-label="Audio streams" fontSize="sm" striped withBorder>
          <thead>
            <tr>
              <th>Stream</th>
              <th>Language</th>
              <th>Title</th>
              <th>Codec</th>
            </tr>
          </thead>
          <tbody>
            {tracks.map((track, index) => (
              <tr key={`${track.id}-${index}`}>
                <td>
                  <Text size="sm">{track.id}</Text>
                </td>
                <td>
                  <Text size="sm">{displayValue(track.language)}</Text>
                </td>
                <td>
                  <Text size="sm">
                    {displayValue(track.title, track.label)}
                  </Text>
                </td>
                <td>
                  <Text size="sm">{displayValue(track.codec)}</Text>
                </td>
              </tr>
            ))}
          </tbody>
        </Table>
      </Box>
    </Stack>
  );
}
