import React, { FC } from 'react';
import { Menu, Button, Text, Slider, Stack } from '@mantine/core';
import {
  IconDashboardFilled,
  IconTextCaption,
  IconLanguage,
  IconChevronDown,
  IconLetterT
} from '@tabler/icons-react';
import { AudioTrack, SubtitleTrack } from '@/domain/Messages';
import { BUTTON_COLOUR } from '@/domain/Constants';

interface PlaybackSpeedControlProps {
  currentRate: number;
  onRateChange: (rate: number) => void;
}

// Viewport-based responsive sizing
const MENU_WIDTH = 'min(450px, 80vw)';
const MENU_SX = { fontSize: 'min(1.5vw, 2vh)' };
const MENU_LABEL_SX = { fontSize: 'min(2vw, 3vh)', fontWeight: 700 as const };
// Smaller icons for bottom media controls (relative to main control buttons)
const MEDIA_ICON_STYLE = { width: 'min(3vw, 4vh)', height: 'min(3vw, 4vh)' };
const MEDIA_CHEVRON_STYLE = { width: 'min(2vw, 2.5vh)', height: 'min(2vw, 2.5vh)' };
const BUTTON_STYLE = {
  color: 'white',
  fontSize: 'min(1.5vw, 2.5vh)',
  padding: 'min(1.5vw, 2vh) min(2vw, 3vh)',
  minHeight: 'min(6vw, 8vh)',  // Ensure minimum height for icon + text
  backgroundColor: BUTTON_COLOUR,
  display: 'flex',
  alignItems: 'center',
  '&:hover': {
    backgroundColor: 'rgba(25, 113, 194, 0.9)',
  }
};

/** Maps common ISO 639-2/B and 639-1 language codes to full names */
const LANGUAGE_NAMES: Record<string, string> = {
  eng: 'English', en: 'English',
  spa: 'Spanish', es: 'Spanish',
  fre: 'French', fra: 'French', fr: 'French',
  ger: 'German', deu: 'German', de: 'German',
  ita: 'Italian', it: 'Italian',
  por: 'Portuguese', pt: 'Portuguese',
  rus: 'Russian', ru: 'Russian',
  jpn: 'Japanese', ja: 'Japanese',
  chi: 'Chinese', zho: 'Chinese', zh: 'Chinese',
  kor: 'Korean', ko: 'Korean',
  ara: 'Arabic', ar: 'Arabic',
  hin: 'Hindi', hi: 'Hindi',
  tha: 'Thai', th: 'Thai',
  vie: 'Vietnamese', vi: 'Vietnamese',
  pol: 'Polish', pl: 'Polish',
  dut: 'Dutch', nld: 'Dutch', nl: 'Dutch',
  swe: 'Swedish', sv: 'Swedish',
  dan: 'Danish', da: 'Danish',
  nor: 'Norwegian', no: 'Norwegian',
  fin: 'Finnish', fi: 'Finnish',
  tur: 'Turkish', tr: 'Turkish',
  heb: 'Hebrew', he: 'Hebrew',
  ind: 'Indonesian', id: 'Indonesian',
  may: 'Malay', msa: 'Malay', ms: 'Malay',
  und: 'Unknown',
};

function getAudioTrackLabel(track: AudioTrack): string {
  const lang = LANGUAGE_NAMES[track.language?.toLowerCase() ?? ''] || track.label || track.language || `Track ${track.id + 1}`;
  const codec = track.codec ? ` (${track.codec.toUpperCase()})` : '';
  const def = track.default ? ' (default)' : '';
  return `${lang}${codec}${def}`;
}

export const PlaybackSpeedControl: FC<PlaybackSpeedControlProps> = ({ currentRate, onRateChange }) => {
  const presetSpeeds = [0.5, 0.6, 0.7, 0.8, 0.9, 1];

  return (
    <Menu shadow="md" width={MENU_WIDTH}>
      <Menu.Target>
        <Button
          rightIcon={<IconChevronDown style={MEDIA_CHEVRON_STYLE} />}
          sx={BUTTON_STYLE}
        >
          <IconDashboardFilled style={MEDIA_ICON_STYLE} />
          <Text ml="xl" sx={{ fontSize: 'min(1.5vw, 2.5vh)' }}>{currentRate}x</Text>
        </Button>
      </Menu.Target>

      <Menu.Dropdown>
        <Menu.Label sx={MENU_LABEL_SX}>Playback Speed</Menu.Label>
        <Stack p="xl">
          <Slider
            value={currentRate}
            onChange={onRateChange}
            min={0.5}
            max={1}
            step={0.1}
            marks={presetSpeeds.map(speed => ({ value: speed, label: `${speed}x` }))}
          />
        </Stack>
        <Menu.Divider />
        {presetSpeeds.map(speed => (
          <Menu.Item 
            key={speed} 
            onClick={() => onRateChange(speed)}
            sx={{ fontWeight: currentRate === speed ? 'bold' : 'normal', ...MENU_SX }}
          >
            {speed}x {speed === 1 && '(Normal)'}
          </Menu.Item>
        ))}
      </Menu.Dropdown>
    </Menu>
  );
};

interface AudioTrackSelectorProps {
  tracks: AudioTrack[];
  currentTrackId: number;
  onTrackChange: (trackId: number) => void;
}

export const AudioTrackSelector: FC<AudioTrackSelectorProps> = ({ tracks, currentTrackId, onTrackChange }) => {
  if (tracks.length <= 1) return null;

  return (
    <Menu shadow="md" width={MENU_WIDTH}>
      <Menu.Target>
        <Button
          variant="subtle"
          rightIcon={<IconChevronDown style={MEDIA_CHEVRON_STYLE} />}
          sx={BUTTON_STYLE}
        >
          <IconLanguage style={MEDIA_ICON_STYLE} />
          <Text ml="xl" sx={{ fontSize: 'min(1.5vw, 2.5vh)' }}>Audio</Text>
        </Button>
      </Menu.Target>

      <Menu.Dropdown sx={{ maxHeight: '60vh', overflowY: 'auto' }}>
        <Menu.Label sx={MENU_LABEL_SX}>Audio Track</Menu.Label>
        {tracks.map(track => (
          <Menu.Item
            key={track.id}
            onClick={() => onTrackChange(track.id)}
            sx={{ fontWeight: currentTrackId === track.id ? 'bold' : 'normal', ...MENU_SX }}
          >
            {getAudioTrackLabel(track)}
          </Menu.Item>
        ))}
      </Menu.Dropdown>
    </Menu>
  );
};

interface SubtitleSelectorProps {
  tracks: SubtitleTrack[];
  currentTrackId: number | null;
  onTrackChange: (trackId: number | null) => void;
}

export const SubtitleSelector: FC<SubtitleSelectorProps> = ({ tracks, currentTrackId, onTrackChange }) => {
  return (
    <Menu shadow="md" width={MENU_WIDTH}>
      <Menu.Target>
        <Button
          variant="subtle"
          rightIcon={<IconChevronDown style={MEDIA_CHEVRON_STYLE} />}
          sx={BUTTON_STYLE}
        >
          <IconTextCaption style={MEDIA_ICON_STYLE} />
          <Text ml="xl" sx={{ fontSize: 'min(1.5vw, 2.5vh)' }}>Subs</Text>
        </Button>
      </Menu.Target>

      <Menu.Dropdown>
        <Menu.Label sx={MENU_LABEL_SX}>Subtitles</Menu.Label>
        <Menu.Item
          onClick={() => onTrackChange(null)}
          sx={{ fontWeight: currentTrackId === null ? 'bold' : 'normal', ...MENU_SX }}
        >
          Off
        </Menu.Item>
        <Menu.Divider />
        {tracks.filter(t => ['es', 'eng', 'en', 'spa'].includes(t.language?.toLowerCase() ?? '')).map(track => (
          <Menu.Item
            key={track.id}
            onClick={() => onTrackChange(track.id)}
            sx={{ fontWeight: currentTrackId === track.id ? 'bold' : 'normal', ...MENU_SX }}
          >
            {track.label} {track.language && `(${track.language})`}
          </Menu.Item>
        ))}
      </Menu.Dropdown>
    </Menu>
  );
}; 

interface SubtitleFontSizeControlProps {
  fontSizePx: number;
  onChange: (sizePx: number) => void;
}

export const SubtitleFontSizeControl: FC<SubtitleFontSizeControlProps> = ({ fontSizePx, onChange }) => {
  const min = 24;
  const max = 72;
  const step = 12;
  const marks = [24, 48, 72].map(v => ({ value: v, label: `${v}px` }));

  return (
    <Menu shadow="md" width={MENU_WIDTH}>
      <Menu.Target>
        <Button
          variant="subtle"
          rightIcon={<IconChevronDown style={MEDIA_CHEVRON_STYLE} />}
          sx={BUTTON_STYLE}
        >
          <IconLetterT style={MEDIA_ICON_STYLE} />
          <Text ml="xl" sx={{ fontSize: 'min(1.5vw, 2.5vh)' }}>{fontSizePx}px</Text>
        </Button>
      </Menu.Target>

      <Menu.Dropdown>
        <Menu.Label sx={MENU_LABEL_SX}>Subtitle Size</Menu.Label>
        <Stack p="xl">
          <Slider
            value={fontSizePx}
            onChange={onChange}
            min={min}
            max={max}
            step={step}
            marks={marks}
          />
        </Stack>
      </Menu.Dropdown>
    </Menu>
  );
}; 