import React, { useImperativeHandle, useEffect, forwardRef, useRef, ForwardedRef, useState } from 'react';
import { AudioTrack, PlayRequest, RemoteMessage, SubtitleTrack } from '@/domain/Messages';
import { log_info, log_warning } from "@/services/Logger";
import { convertFileSrc } from "@tauri-apps/api/core";
import { isTauri } from "@/utils/browserCompat";
import { getNextCue, getPreviousCue } from '@/utils/vttParser';
import { authenticatedMediaUrl, subtitleUrl } from '@/services/mediaUrls';
import { AudioPlayer } from './AudioPlayer';

export enum PlayState {
  STOPPED = 1,
  PAUSED,
  STARTED,
  ERROR
}

export interface PlayerHandlers {
  play: () => void;
  stop: () => void;
  pause: () => void;
  seek: (interval: number) => void;
  seekToSubtitle: (direction: 'previous' | 'next') => void;
  isPlaying: () => boolean;
  setPlaybackRate: (rate: number) => void;
  setAudioTrack: (trackId: number) => void;
  setSubtitleTrack: (trackId: number | null) => void;
  getAvailableAudioTracks: () => AudioTrack[];
  getAvailableSubtitleTracks: () => SubtitleTrack[];
  setSubtitleFontSize: (sizePx: number) => void;
  getSubtitleFontSize: () => number;
}

export interface PlayerProps {
  currentVideo: PlayRequest;
  onStateChange: (state: PlayState) => void;
  onMessage?: (message: RemoteMessage) => void;
  isPlaying?: boolean;
  seekEvent?: number;
  onSeekHandled?: () => void;
  audioOnly?: boolean;
}


const Player = forwardRef((props: PlayerProps, ref: ForwardedRef<PlayerHandlers>) => {
  const videoRef = useRef<HTMLMediaElement | null>(null);
  const counter = useRef(0);
  const currentSubtitleTrack = useRef<number | null>(null);
  const [playError, setPlayError] = useState<string>();

  const play = () => {
    const media = videoRef.current;
    if (!media) return;
    setPlayError(undefined);
    void media.play().catch((error: unknown) => {
      if (videoRef.current !== media || (error instanceof DOMException && error.name === 'AbortError')) return;
      setPlayError('Playback could not start. Press play to try again.');
      props.onStateChange(PlayState.ERROR);
      sendPlayerState(media);
    });
  };
  
  // Subtitle font sizing support
  const subtitleStyleRef = useRef<HTMLStyleElement | null>(null);
  const subtitleFontPxRef = useRef<number>(24);
  const ensureSubtitleStyle = () => {
    if (!subtitleStyleRef.current) {
      const el = document.createElement('style');
      el.setAttribute('data-subtitle-style', 'true');
      document.head.appendChild(el);
      subtitleStyleRef.current = el;
    }
  };
  const updateSubtitleStyle = () => {
    ensureSubtitleStyle();
    const id = props.currentVideo.videoId.replace(/"/g, '\\"');
    const px = subtitleFontPxRef.current;
    if (subtitleStyleRef.current) {
      subtitleStyleRef.current.textContent = `video[data-player-id="${id}"]::cue { font-size: ${px}px; }`;
    }
  };
  useEffect(() => {
    updateSubtitleStyle();
    return () => {
      if (subtitleStyleRef.current) {
        subtitleStyleRef.current.remove();
        subtitleStyleRef.current = null;
      }
    };
  }, [props.currentVideo.videoId]);
  
  const seekEvent = props.seekEvent;

  // Define the handlers that will be exposed through the ref
  useImperativeHandle(ref, () => ({
    play,
    stop: () => videoRef.current?.pause(),
    pause: () => {
      if (videoRef.current) {
        if (videoRef.current.paused) {
          play();
        } else {
          videoRef.current.pause();
        }
      }
    },
    seek: (interval: number) => {
      if (videoRef.current) {
        videoRef.current.currentTime = Math.max(0, videoRef.current.currentTime + interval);
      }
    },
    seekToSubtitle: (direction) => {
      const media = videoRef.current;
      const trackId = currentSubtitleTrack.current;
      if (!media || trackId === null) return;
      const cues = Array.from(media.textTracks[trackId]?.cues ?? []).map((cue) => ({
        startTime: cue.startTime,
        endTime: cue.endTime,
        text: (cue as VTTCue).text,
      }));
      const cue = direction === 'next'
        ? getNextCue(cues, media.currentTime)
        : getPreviousCue(cues, media.currentTime);
      if (cue) media.currentTime = cue.startTime;
    },
    isPlaying: () => {
      return videoRef.current ? !videoRef.current.paused : false;
    },
    setPlaybackRate: (rate: number) => {
      if (videoRef.current) {
        videoRef.current.playbackRate = rate;
        props.onMessage?.({ SetPlaybackRate: { rate } });
      }
    },
    setAudioTrack: (trackId: number) => {
      if (!videoRef.current) return;

      const savedTime = videoRef.current.currentTime;
      const wasPaused = videoRef.current.paused;

      // Build the remux URL: /api/stream-audio/{trackId}/{collection}/{video}
      const url = new URL(props.currentVideo.url, window.location.href);
      if (!url.pathname.startsWith('/api/stream/')) return;
      url.pathname = url.pathname.replace('/api/stream/', `/api/stream-audio/${trackId}/`);
      const newUrl = authenticatedMediaUrl(url.href);

      const video = videoRef.current;

      const onLoaded = () => {
        video.currentTime = savedTime;
        if (!wasPaused) {
          play();
        }
        video.removeEventListener('loadedmetadata', onLoaded);
      };

      video.addEventListener('loadedmetadata', onLoaded);
      video.src = newUrl;
      video.load();

      props.onMessage?.({ SetAudioTrack: { trackId } });
    },
    setSubtitleTrack: (trackId: number | null) => {
      if (videoRef.current && videoRef.current.textTracks) {
        const textTracks = Array.from(videoRef.current.textTracks);
        textTracks.forEach((track, index) => {
          track.mode = index === trackId ? 'showing' : 'disabled';
        });
        currentSubtitleTrack.current = trackId;
        props.onMessage?.({ SetSubtitleTrack: { trackId } });
        sendPlayerState(videoRef.current);
      }
    },
    getAvailableAudioTracks: () => {
      // Try native API first (Safari/Tauri WebView)
      type Track = { enabled: boolean; language?: string; label?: string };
      type V = HTMLVideoElement & { audioTracks?: { length: number; [index: number]: Track } };
      const v = videoRef.current as V | null;
      if (v && v.audioTracks && v.audioTracks.length > 0) {
        const audioTracks: Track[] = Array.from({ length: v.audioTracks.length }, (_, i) => v.audioTracks![i]);
        return audioTracks.map((track: Track, index: number) => ({
          id: index,
          language: track.language || 'Unknown',
          label: track.label || `Track ${index + 1}`,
          default: !!track.enabled
        }));
      }
      // Fallback to backend metadata
      const audioTrackList = props.currentVideo.metadata?.audioTrackList;
      if (audioTrackList && audioTrackList.length > 0) {
        return audioTrackList.map((t, index) => ({
          id: t.id ?? index,
          language: t.language || 'Unknown',
          label: t.label || `Track ${index + 1}`,
          codec: t.codec,
          default: !!t.default
        }));
      }
      return [];
    },
    getAvailableSubtitleTracks: () => {
      if (videoRef.current && videoRef.current.textTracks) {
        const list = Array.from(videoRef.current.textTracks);
        if (list.length > 0) {
          return list.map((track, index) => ({
            id: index,
            language: track.language || 'Unknown',
            label: track.label || `Subtitle ${index + 1}`,
            format: track.kind,
            default: track.mode === 'showing'
          }));
        }
      }
      const withMeta = props.currentVideo;
      const subtitleTracks = withMeta.metadata?.subtitleTracks;
      if (subtitleTracks && subtitleTracks.length > 0) {
        return subtitleTracks.map((t, index) => ({
          id: index,
          language: t.language || 'Unknown',
          label: t.label || (t.language || `Subtitle ${index + 1}`),
          format: 'subtitles',
          default: !!t.default
        }));
      }
      return [];
    },
    setSubtitleFontSize: (sizePx: number) => {
      subtitleFontPxRef.current = sizePx;
      updateSubtitleStyle();
    },
    getSubtitleFontSize: () => subtitleFontPxRef.current,
  }));

  // The remote adapter supplies commands; local controls use the ref directly.
  useEffect(() => {
    if (videoRef.current && seekEvent !== undefined) {
      videoRef.current.currentTime = Math.max(0, videoRef.current.currentTime + seekEvent);
      props.onSeekHandled?.();
    }
  }, [seekEvent, props.onSeekHandled]);

  // Only the remote adapter controls playback through this prop.
  useEffect(() => {
    if (videoRef.current && props.isPlaying !== undefined) {
      if (props.isPlaying && videoRef.current.paused) {
        play();
      } else if (!props.isPlaying && !videoRef.current.paused) {
        videoRef.current.pause();
      }
    }
  }, [props.isPlaying, props.currentVideo]);

  // Set up subtitle tracks when video loads
  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;

    const handleLoadedMetadata = () => {
      Array.from(video.querySelectorAll('track[data-generated="true"][kind="subtitles"]')).forEach((el) => el.remove());
      const withMeta = props.currentVideo;
      const subtitleTracks = withMeta.metadata?.subtitleTracks;
      if (subtitleTracks && subtitleTracks.length > 0) {
        subtitleTracks.forEach((track, index) => {
          const language = track.language || 'und';
          const src = track.url || subtitleUrl(props.currentVideo.url, language);
          const trackElement = document.createElement('track');
          trackElement.setAttribute('data-generated', 'true');
          trackElement.kind = 'subtitles';
          trackElement.label = track.label || language;
          trackElement.srclang = language;
          trackElement.src = authenticatedMediaUrl(src);
          if (track.default) {
            trackElement.default = true;
            currentSubtitleTrack.current = index;
          }
          video.appendChild(trackElement);
        });
      }

      updateSubtitleStyle();
      sendPlayerState(video);
    };

    if (video.readyState >= 1) {
      handleLoadedMetadata();
    } else {
      video.addEventListener('loadedmetadata', handleLoadedMetadata);
    }
    return () => {
      video.removeEventListener('loadedmetadata', handleLoadedMetadata);
    };
  }, [props.currentVideo]);

  const getNextVideo = () => {
    log_info(`Video completed: ${props.currentVideo.video}`);
  };

  const logVideoError = () => {
    log_warning(`Error playing: ${props.currentVideo.video}`);
    setPlayError('This media could not be played. Check the connection and file format.');
    props.onStateChange(PlayState.ERROR);
    if (videoRef.current) sendPlayerState(videoRef.current);
  };

  const getVideoUrl = () => {
    try {
      if (isTauri()) {
        return convertFileSrc(props.currentVideo.url);
      }
    } catch {
    }
    return authenticatedMediaUrl(props.currentVideo.url);
  };

  const sendPlayerState = (player: HTMLMediaElement) => {
    const playerState = {
      State: {
        collection: props.currentVideo.collection,
        video: props.currentVideo.video,
        videoId: props.currentVideo.videoId,
        currentSrc: props.currentVideo.url,
        currentTime: player.currentTime,
        duration: Number.isFinite(player.duration) ? player.duration : 0,
        paused: player.paused,
        playbackRate: player.playbackRate,
        currentSubtitleTrack: currentSubtitleTrack.current,
        availableSubtitleTracks: props.currentVideo.metadata?.subtitleTracks,
      },
    };
    props.onMessage?.(playerState);
  };

  const onTimeUpdate = (e: React.SyntheticEvent<HTMLMediaElement>) => {
    const player = e.currentTarget;

    if (counter.current % 3 === 0) {
      sendPlayerState(player);
    }
    counter.current++;
  };

  const onPlaybackStateChange = (e: React.SyntheticEvent<HTMLMediaElement>) => {
    const player = e.currentTarget;
    // Native controls can resume before a queued pause event is delivered (and
    // vice versa). Report the current state so the remote adapter won't undo it.
    if (!player.paused) setPlayError(undefined);
    props.onStateChange(player.paused ? PlayState.PAUSED : PlayState.STARTED);
    sendPlayerState(player);
  };

  const onKeyPressed = (evt: React.KeyboardEvent<HTMLMediaElement>) => {
    switch (evt.key) {
      case " ":
        evt.preventDefault();
        if (videoRef.current?.paused) {
          play();
        } else {
          videoRef.current?.pause();
        }
        break;
    }
  };

  const mediaProps = {
      ref: (media: HTMLMediaElement | null) => { videoRef.current = media; },
      src: getVideoUrl(),
      style: { width: '100%', height: '100%', objectFit: 'contain' as const },
      controls: true,
      autoPlay: true,
      crossOrigin: 'anonymous' as const,
      'aria-label': props.currentVideo.video,
      'data-player-id': props.currentVideo.videoId,
      onPlay: onPlaybackStateChange,
      onPause: onPlaybackStateChange,
      onEnded: (e: React.SyntheticEvent<HTMLMediaElement>) => {
        getNextVideo();
        props.onStateChange(PlayState.STOPPED);
        sendPlayerState(e.currentTarget);
      },
      onSeeked: (e: React.SyntheticEvent<HTMLMediaElement>) => sendPlayerState(e.currentTarget),
      onRateChange: (e: React.SyntheticEvent<HTMLMediaElement>) => sendPlayerState(e.currentTarget),
      onError: logVideoError,
      onTimeUpdate,
      onKeyDown: onKeyPressed,
  };

  return (
    <>
      {props.audioOnly ? (
        <AudioPlayer mediaRef={videoRef}>
          <audio {...mediaProps} style={{ width: '100%', height: 54, flexShrink: 0 }} />
        </AudioPlayer>
      ) : <video {...mediaProps} playsInline />}
      {playError && <div role="alert">{playError}</div>}
    </>
  );
});

export default Player;
