import { ChildCollection } from "@/domain/Messages";
import { Card, Center, Image, Text, useMantineTheme } from "@mantine/core";
import { IconFolder } from "@tabler/icons-react";
import { FC } from "react";
import { getCardSizes, getCleanName, getThumbnail } from "@/domain/Utils";
import { useMediaQuery } from "@mantine/hooks";

export const CollectionCard: FC<{
  collection: ChildCollection;
  onClick: (collection: string) => void;
}> = ({ collection, onClick }) => {
  const theme = useMantineTheme();
  const useSmallImages = useMediaQuery(`(max-width: ${theme.breakpoints.xl})`);
  const dimensions = getCardSizes(useSmallImages);
  const displayName = collection.collection
    ? getCleanName(collection.collection)
    : "Others";
  const thumbnail = getThumbnail(collection.thumbnail, dimensions.imgWidth);
  return (
    <Card
      component="button"
      type="button"
      onClick={() => onClick(collection.collection)}
      aria-label={`Open ${displayName}`}
      w={dimensions.imgWidth}
      maw="100%"
      radius="lg"
      withBorder
      sx={{
        textAlign: "left",
        cursor: "pointer",
        "&:hover": { borderColor: "#536273" },
      }}
    >
      <Card.Section
        className="library-cover"
        sx={{ height: dimensions.imgHeight }}
      >
        {thumbnail ? (
          <Image
            height="100%"
            fit="cover"
            src={thumbnail}
            alt={`image from ${collection.collection}`}
          />
        ) : (
          <Center h="100%" bg="dark.5">
            <IconFolder color="#8CE4CD" size={52} stroke={1.2} />
          </Center>
        )}
      </Card.Section>
      <Card.Section p={16} mih={dimensions.footerHeight}>
        <Text size="xs" color="dimmed" mb={4}>
          COLLECTION
        </Text>
        <Text weight={500} lineClamp={2}>
          {displayName}
        </Text>
      </Card.Section>
    </Card>
  );
};
