import {
  Card,
  createStyles,
  Grid,
  HoverCard,
  Image,
  RingProgress,
  Stack,
  Text,
  useMantineTheme,
} from "@mantine/core";
import { useMediaQuery } from "@mantine/hooks";
import React, { Dispatch, FC, SetStateAction } from "react";
import { VideoDetails } from "../../domain/Messages";
import { VideoDetailsImpl } from "../../domain/Models";
import { Player } from "../../services/Player";
import { getCardSizes, getThumbnail } from "@/domain/Utils";
import {
  getVideoProcessingStatus,
  isVideoPlayable,
  isAudioOnly,
} from "@/domain/VideoProcessingState";
import { VideoWrapper } from "@/domain/VideoWrapper";
import { getDescription } from "./Utils";
import { VideoMenu } from "./VideoMenu";
import {
  VideoProcessingBadge,
  VideoThumbnailPlaceholder,
} from "./VideoProcessingStatus";

// Create styles using Mantine's createStyles
const useStyles = createStyles((theme) => ({
  title: {
    fontWeight: 500,
    fontSize: theme.fontSizes.lg,
  },
}));

interface IVideoCard {
  video: VideoDetails;
  player: Player;
  setDialog: Dispatch<SetStateAction<JSX.Element>>;
  back: () => void;
}

export const VideoCard: FC<IVideoCard> = ({
  video,
  player,
  setDialog,
  back,
}) => {
  const { classes } = useStyles();
  const helper = new VideoWrapper(video);

  const playVideo = (player: Player, video?: VideoDetails) => {
    if (typeof video !== "undefined") {
      player.playVideo(video);
    }
  };

  const description = getDescription(new VideoDetailsImpl(video));
  const theme = useMantineTheme();
  const useSmallImages = useMediaQuery(`(max-width: ${theme.breakpoints.xl})`);
  const dimensions = getCardSizes(useSmallImages);
  const thumbnail = getThumbnail(video.thumbnail, dimensions.imgWidth);
  const status = getVideoProcessingStatus(video.state);
  const playable = isVideoPlayable(video);

  const image = thumbnail ? (
    <Image
      maw={dimensions.imgWidth}
      mx="auto"
      radius="md"
      fit="cover"
      src={thumbnail}
      alt={`image from ${helper.name()}`}
    />
  ) : (
    <VideoThumbnailPlaceholder
      state={video.state}
      audioOnly={isAudioOnly(video)}
      height={dimensions.imgHeight}
    />
  );

  const playPercentage = helper.getPercentPlayed();
  const ringColour = "mint";
  const ringProgress =
    playPercentage === 0 ? null : (
      <RingProgress
        sx={{
          zIndex: 1,
          position: "absolute",
          top: 10,
          left: 10,
          borderRadius: "50%",
          backgroundColor: "#0A0E14D9",
        }}
        sections={[{ value: playPercentage, color: ringColour }]}
        size={60}
        label={
          <Text color={ringColour} weight={500} align="center" size="sm">
            {playPercentage}%
          </Text>
        }
      />
    );

  const title = (
    <HoverCard shadow="md">
      <HoverCard.Target>
        <Text
          fz="md"
          weight={500}
          lineClamp={2}
          sx={{ cursor: playable ? "pointer" : "default" }}
          onClick={() => playable && playVideo(player, video)}
        >
          {helper.displayName()}
        </Text>
      </HoverCard.Target>
      <HoverCard.Dropdown>{description}</HoverCard.Dropdown>
    </HoverCard>
  );

  const card = (
    <Stack w={dimensions.imgWidth} maw="100%">
      <Card shadow="sm" padding="md" radius="lg" withBorder>
        <Card.Section
          className="library-cover"
          role={playable ? "button" : undefined}
          tabIndex={playable ? 0 : undefined}
          aria-label={playable ? `Play ${helper.displayName()}` : undefined}
          onKeyDown={(event) => {
            if (playable && (event.key === "Enter" || event.key === " ")) {
              event.preventDefault();
              playVideo(player, video);
            }
          }}
          sx={{
            height: dimensions.imgHeight,
            position: "relative",
            overflow: "hidden",
            cursor: playable ? "pointer" : "default",
          }}
          onClick={() => playable && playVideo(player, video)}
        >
          {ringProgress}
          {image}
        </Card.Section>
        <Card.Section>
          <Grid>
            <Grid.Col
              data-testid="video-card-footer"
              style={{
                position: "relative",
                padding: "16px 60px 16px 16px",
                minHeight: status
                  ? dimensions.footerHeight + 32
                  : dimensions.footerHeight,
              }}
              span={12}
              className={classes.title}
            >
              {status && <VideoProcessingBadge state={video.state} />}
              {title}
              <VideoMenu
                setDialog={setDialog}
                back={back}
                player={player}
                helper={helper}
              />
            </Grid.Col>
          </Grid>
        </Card.Section>
      </Card>
    </Stack>
  );

  return card;
};
