import VideoTab from "./Video/VideoTab";
import { Search } from "./Search/Search";
import { TasksTab } from "./Tasks/TasksTab";
import { HostConfig, VideoDetails } from "../domain/Messages";
import { useMemo, useRef, useState } from "react";
import { PlaybackControls, VideoPlayer } from "../services/Player";
import { Alert, gAlertManager } from "./Base/Alert";
import { CardModal } from "./Base/Modal";
import { VideoItemDetail } from "./Video/VideoDetail";
import { SpeedDialer } from "./SpeedDialer";
import { useTabVisibility } from "@/services/helpers";
import {
  Container,
  Portal,
  Group,
  SegmentedControl,
  Text,
  Box,
} from "@mantine/core";
import { CurrentlyPlayingDetails } from "./Video/CurrentlyPlayingDetails";
import { socketRetryConnect } from "@/domain/Store/SocketMiddleware";
import { useDispatch } from "react-redux";
import { ConnectionIndicator } from "./Base/ConnectionIndicator";
import {
  LocalPlayback,
  LocalPlaybackHandle,
  LocalPlaybackState,
} from "./Viewer/LocalPlayback";
import { isAndroidApp } from "@/utils/browserCompat";
import { NativePlayback } from "./Viewer/NativePlayback";
import { LegacyPlayerAppearance } from "./Base/Appearance";
import { IconStack2 } from "@tabler/icons-react";

enum CardNames {
  Videos,
  CurrentVideo,
  Search,
  Tasks,
  VideoDetail,
}

/**
 * The main component of the application.
 * @param {HostConfig} props - The host configuration.
 */
export const Main = (props: HostConfig) => {
  const [activeCard, setActiveCard] = useState<CardNames>(CardNames.Videos);
  const [alertVisible, setAlertVisible] = useState<boolean>(false);
  const [dialog, setDialog] = useState<JSX.Element>(<></>);
  const [currentVideo, setCurrentVideo] = useState<VideoDetails | null>(null);
  const androidApp = isAndroidApp();
  const LocalPlayer = androidApp ? NativePlayback : LocalPlayback;
  const [selectedPlaybackTarget, setPlaybackTarget] = useState("remote");
  const playbackTarget = androidApp ? "local" : selectedPlaybackTarget;
  const [localPlayback, setLocalPlayback] = useState<LocalPlaybackState>();
  const localPlayerRef = useRef<LocalPlaybackHandle>(null);
  const videoPlayer = useMemo(() => {
    const localControls: PlaybackControls = {
      playVideo: (video) => localPlayerRef.current?.playVideo(video),
      seek: (interval) => localPlayerRef.current?.seek(interval),
      togglePause: () => localPlayerRef.current?.togglePause(),
      setSubtitleTrack: (trackId) =>
        localPlayerRef.current?.setSubtitleTrack(trackId),
      seekToSubtitle: (direction) =>
        localPlayerRef.current?.seekToSubtitle(direction),
    };
    return new VideoPlayer(
      props.host,
      "",
      playbackTarget === "local" ? localControls : undefined,
    );
  }, [props.host, playbackTarget]);
  const dispatch = useDispatch();

  useTabVisibility((newState: string) => {
    if (newState === "visible") {
      dispatch(socketRetryConnect());
    }
  });

  const showVideoDetails = (video: VideoDetails) => {
    setCurrentVideo(video);
    setActiveCard(CardNames.VideoDetail);
  };

  // Determine which component to render based on the active tab.
  const getMainCard = () => {
    const onClose = () => setActiveCard(CardNames.Videos);

    switch (activeCard) {
      case CardNames.Search:
        return (
          <CardModal title={"Search"} onClose={onClose} centered={false}>
            <Search host={props.host} />
          </CardModal>
        );

      case CardNames.Tasks:
        return (
          <CardModal title="Running Tasks" onClose={onClose}>
            <TasksTab host={props.host} isActive={true} />
          </CardModal>
        );

      case CardNames.CurrentVideo:
        return (
          <CardModal title="Current Video" onClose={onClose}>
            <CurrentlyPlayingDetails
              player={videoPlayer}
              setDialog={setDialog}
              back={onClose}
              localPlayback={localPlayback}
              playbackTarget={playbackTarget}
            />
          </CardModal>
        );

      case CardNames.VideoDetail:
        if (currentVideo !== null) {
          const onClose = () => {
            setCurrentVideo(null);
            setActiveCard(CardNames.Videos);
          };

          return (
            <CardModal title="Video Details" onClose={onClose}>
              <VideoItemDetail
                video={
                  playbackTarget === "local" &&
                  localPlayback?.video.checksum === currentVideo.checksum
                    ? localPlayback.video
                    : currentVideo
                }
                setDialog={setDialog}
                back={() => setCurrentVideo(null)}
                player={videoPlayer}
                playerState={
                  playbackTarget === "local" &&
                  localPlayback?.video.checksum === currentVideo.checksum
                    ? localPlayback.state
                    : undefined
                }
              />
            </CardModal>
          );
        }
    }

    return <></>;
  };

  const localPlayer = (
    <LocalPlayer
      ref={localPlayerRef}
      host={props.host}
      active={playbackTarget === "local"}
      onChange={setLocalPlayback}
      onStart={() => {
        setActiveCard(CardNames.Videos);
        setDialog(<></>);
      }}
    />
  );

  // Set the alert visibility state based on the global alert manager.
  gAlertManager.setStateFunction(setAlertVisible);

  return (
    <>
      <Container size={1180} className="media-app app-shell">
        <Group position="apart" className="app-header" spacing="md">
          <Group spacing={10} noWrap>
            <Box className="brand-mark">
              <IconStack2 size={21} stroke={1.6} />
            </Box>
            <Text weight={600} size="sm">
              Lots of Videos
            </Text>
          </Group>
          <ConnectionIndicator size={20} />
        </Group>
        {!androidApp && (
          <Group spacing="sm" mb={28} className="playback-target">
            <Text size="xs" color="dimmed" id="playback-target-label">
              Play on
            </Text>
            <SegmentedControl
              aria-labelledby="playback-target-label"
              value={playbackTarget}
              data={[
                { value: "local", label: "This device" },
                { value: "remote", label: "Remote player" },
              ]}
              onChange={(target) => {
                if (target === "remote")
                  localPlayerRef.current?.pausePlayback();
                setPlaybackTarget(target);
                setDialog(<></>);
              }}
            />
          </Group>
        )}
        {androidApp ? (
          localPlayer
        ) : (
          <LegacyPlayerAppearance>{localPlayer}</LegacyPlayerAppearance>
        )}
        {getMainCard()}

        {dialog}

        {/* Render the selected main component*/}
        <Box>
          <VideoTab
            videoPlayer={videoPlayer}
            isActive={activeCard === CardNames.Videos}
            showVideoDetails={showVideoDetails}
          />
        </Box>

        <SpeedDialer
          showLibrary={() => setActiveCard(CardNames.Videos)}
          active={
            activeCard === CardNames.Search
              ? "search"
              : activeCard === CardNames.Tasks
                ? "tasks"
                : activeCard === CardNames.CurrentVideo
                  ? "playing"
                  : "library"
          }
          showCurrentVideo={() => setActiveCard(CardNames.CurrentVideo)}
          showSearch={() => setActiveCard(CardNames.Search)}
          showTasks={() => setActiveCard(CardNames.Tasks)}
        />
      </Container>
      {/* Render the global alert component. */}
      <Portal>
        <Alert show={alertVisible} />
      </Portal>
    </>
  );
};
