import {
  AudioAnalyser,
  AudioReaction,
  createAudioReactivity,
} from "./audioReactivity";
import { createVisualizerFeedback, Flow } from "./visualizerFeedback";

type Point = [number, number];
type Pattern =
  | "ring"
  | "star"
  | "spiral"
  | "curtains"
  | "lattice"
  | "tunnel"
  | "butterfly"
  | "orbits"
  | "ribbons"
  | "cross"
  | "lissajous";
interface Scene {
  pattern: Pattern;
  flow: Flow;
  layers: number;
  dots: number;
}
const TAU = Math.PI * 2;
const smooth = (value: number) => value * value * (3 - 2 * value);
const mix = (from: number, to: number, amount: number) =>
  from + (to - from) * amount;

// Most hues stay close, with occasional warm/cool accents. Each layer and its
// dust pick up a different part of the palette, while old trails keep their hue.
const palettes = [
  [150, 185, 205],
  [20, 45, 340],
  [255, 290, 195],
  [325, 355, 35],
  [190, 225, 160],
  [50, 80, 14],
  [278, 310, 40],
  [12, 41, 180],
  [155, 210, 280],
] as const;
function paletteColor(time: number, channel: number, light = 0) {
  const position = time / 13;
  const index = Math.floor(position) % palettes.length;
  const amount = smooth(Math.max(0, ((position % 1) - 0.2) / 0.8));
  const from = palettes[index][channel % 3];
  const to = palettes[(index + 1) % palettes.length][channel % 3];
  const hueDelta = ((to - from + 540) % 360) - 180;
  return `hsl(${from + hueDelta * amount}, 91%, ${Math.min(90, 55 + light)}%)`;
}

// Each family has its own movement, density, and depth. Changing geometry and
// flow together creates different scenes without adding stronger beat pulses.
const scenes: readonly Scene[] = [
  { pattern: "ring", flow: [0.23, 0.14, 0.12, 0.025], layers: 2, dots: 0 },
  { pattern: "star", flow: [0.18, -0.2, 0.07, -0.015], layers: 2, dots: 0.12 },
  { pattern: "spiral", flow: [-0.16, 0.38, 0.11, 0.02], layers: 2, dots: 0.32 },
  {
    pattern: "curtains",
    flow: [0.04, -0.05, 0.23, 0.17],
    layers: 4,
    dots: 0.08,
  },
  {
    pattern: "lattice",
    flow: [0.14, 0.16, 0.09, -0.09],
    layers: 4,
    dots: 0.58,
  },
  { pattern: "tunnel", flow: [-0.48, 0.32, 0.08, -0.01], layers: 2, dots: 1 },
  {
    pattern: "butterfly",
    flow: [0.12, -0.17, 0.23, 0.05],
    layers: 2,
    dots: 0.12,
  },
  { pattern: "orbits", flow: [0.19, 0.2, 0.06, -0.035], layers: 3, dots: 0.28 },
  { pattern: "ribbons", flow: [0.07, -0.08, 0.17, 0.15], layers: 2, dots: 0 },
  { pattern: "cross", flow: [0.12, -0.06, 0.13, -0.1], layers: 2, dots: 0.08 },
  { pattern: "lissajous", flow: [0.2, 0.1, 0.24, 0.04], layers: 2, dots: 0.18 },
];
const sceneDuration = 11;

function patternPoint(
  pattern: Pattern,
  position: number,
  layer: number,
  time: number,
  signal: AudioReaction,
): Point {
  const angle = position * TAU;
  const phase = time * 0.23;
  const index = Math.min(1023, Math.floor(position * 1023));
  const wave =
    (signal.waveform[index] + signal.waveform[(index + 1) % 1024]) * 0.5;
  const ripple = wave * (0.022 + signal.energy * 0.018);
  const separation = layer * (0.009 + signal.treble * 0.008);
  switch (pattern) {
    case "ring": {
      // A broad, irregular oscilloscope ring rather than orbiting ornaments.
      const radius =
        1 +
        0.12 * Math.sin(angle * 3 + phase) +
        0.06 * Math.sin(angle * 7 - phase * 0.7);
      return [
        Math.cos(angle) * (radius * 0.32 + ripple + separation),
        Math.sin(angle) * (radius * 0.36 + ripple + separation),
      ];
    }
    case "ribbons": {
      // A pair of wide, folded ribbons; the flow field carries them into veils.
      const across = position * 2 - 1;
      return [
        across * 0.57,
        Math.sin(angle * 1.5 + phase) * 0.18 +
          Math.cos(angle * 0.5 - phase * 0.6) * 0.1 +
          ripple * 1.2 +
          separation,
      ];
    }
    case "tunnel": {
      const radius = 0.38 + 0.025 * Math.sin(angle * 11 + phase) + ripple * 0.6;
      return [
        Math.cos(angle + phase * 0.25) * (radius + separation),
        Math.sin(angle + phase * 0.25) * (radius * 1.1 + separation),
      ];
    }
    case "cross": {
      const across = position * 2 - 1;
      return [
        across * 0.57,
        across * (layer === 0 ? 0.38 : -0.38) +
          Math.sin(angle * 1.5 + phase) * 0.055 +
          ripple +
          separation,
      ];
    }
    case "star": {
      // Angular rays belong to the shape; drums only add the same gentle pulse.
      const tooth = 1 - Math.abs(((position * 7 + phase * 0.04) % 1) * 2 - 1);
      const radius = 0.21 + tooth * 0.2 + ripple;
      return [
        Math.cos(angle + phase * 0.13) * radius,
        Math.sin(angle + phase * 0.13) * (radius + separation),
      ];
    }
    case "spiral": {
      const turn = angle * 2.5 + phase + layer * Math.PI;
      const radius = Math.pow(position, 0.8) * 0.43 + ripple * position;
      return [Math.cos(turn) * radius, Math.sin(turn) * radius];
    }
    case "curtains":
      return [
        (layer - 1.5) * 0.19 +
          Math.sin(angle * 1.2 + phase + layer * 0.9) * 0.12 +
          Math.cos(angle * 0.5 - phase) * 0.055 +
          ripple,
        (position * 2 - 1) * 0.58,
      ];
    case "lattice": {
      const across = position * 2 - 1;
      const bend = Math.sin(angle * 0.75 + phase + layer) * 0.085 + ripple;
      const diagonal = across * (layer % 2 === 0 ? 0.32 : -0.32) + bend;
      return layer < 2 ? [across * 0.58, diagonal] : [diagonal, across * 0.58];
    }
    case "butterfly":
      return [
        Math.sin(angle) * (0.34 + Math.cos(angle * 2 + phase) * 0.1) + ripple,
        Math.cos(angle * 2 + phase * 0.4) * 0.27 +
          Math.sin(angle * 3 - phase) * 0.055 +
          ripple +
          separation,
      ];
    case "orbits": {
      const tilt = (layer * Math.PI) / 3 + phase * 0.15;
      const x = Math.cos(angle + phase * 0.3) * (0.4 + ripple);
      const y =
        Math.sin(angle + phase * 0.3) *
        (0.05 + 0.19 * (0.5 + 0.5 * Math.sin(phase * 0.7 + layer)) + ripple);
      return [
        x * Math.cos(tilt) - y * Math.sin(tilt),
        x * Math.sin(tilt) + y * Math.cos(tilt),
      ];
    }
    default:
      return [
        Math.sin(angle * 2 + phase * 0.6) * 0.35 + ripple,
        Math.sin(angle * 3 - phase * 0.4) * 0.31 + ripple + separation,
      ];
  }
}

export function createClassicVisualizer(
  canvas: HTMLCanvasElement,
  context: CanvasRenderingContext2D,
) {
  const reactToAudio = createAudioReactivity();
  const feedback = createVisualizerFeedback(canvas);
  // Software rendering remains available when WebGL is disabled or lost.
  const history = document.createElement("canvas");
  const historyContext = history.getContext("2d", { alpha: false });
  let time = 0;
  let motion = 0;
  let pulse = 0;
  const points = new Float32Array(1026);

  const draw = (elapsed: number, analyser?: AudioAnalyser) => {
    time += elapsed;
    const signal = reactToAudio(elapsed, analyser);
    pulse += (signal.pulse - pulse) * (1 - Math.exp(-elapsed / 0.1));
    motion += elapsed * (0.8 + signal.energy * 0.1);
    const { width, height } = canvas;
    const size = Math.min(width, height);
    const scenePosition = time / sceneDuration;
    const sceneIndex = Math.floor(scenePosition) % scenes.length;
    const scene = scenes[sceneIndex];
    const nextScene = scenes[(sceneIndex + 1) % scenes.length];
    const blend = smooth(Math.max(0, ((scenePosition % 1) - 0.66) / 0.34));
    const flow: Flow = [
      mix(scene.flow[0], nextScene.flow[0], blend),
      mix(scene.flow[1], nextScene.flow[1], blend),
      mix(scene.flow[2], nextScene.flow[2], blend),
      mix(scene.flow[3], nextScene.flow[3], blend),
    ];
    const previous = feedback?.draw(elapsed, motion, flow);
    context.globalCompositeOperation = "source-over";
    context.globalAlpha = 1;
    if (previous) {
      context.drawImage(previous, 0, 0);
    } else if (historyContext) {
      if (history.width !== width || history.height !== height) {
        history.width = width;
        history.height = height;
      }
      historyContext.globalCompositeOperation = "copy";
      historyContext.filter = "contrast(1.025)";
      historyContext.drawImage(canvas, 0, 0);
      context.fillStyle = "#000";
      context.fillRect(0, 0, width, height);
      context.save();
      context.translate(width / 2, height / 2);
      context.rotate(flow[1] * elapsed);
      context.scale(
        Math.exp(elapsed * (flow[0] + flow[3])),
        Math.exp(elapsed * (flow[0] - flow[3])),
      );
      context.drawImage(history, -width / 2, -height / 2);
      context.restore();
      context.fillStyle = `rgba(0,0,0,${1 - Math.exp(-elapsed * 0.55)})`;
      context.fillRect(0, 0, width, height);
    } else {
      context.fillStyle = "#000";
      context.fillRect(0, 0, width, height);
    }

    const pointCloud = mix(scene.dots, nextScene.dots, blend);
    const centerX = width * (0.5 + Math.sin(motion * 0.17) * 0.045);
    const centerY = height * (0.5 + Math.cos(motion * 0.13) * 0.04);
    const breathing = 1 + pulse * 0.035;
    context.lineJoin = "round";
    context.lineCap = "round";
    for (
      let layer = 0;
      layer < Math.max(scene.layers, nextScene.layers);
      layer++
    ) {
      const visibility = mix(
        layer < scene.layers ? 1 : 0,
        layer < nextScene.layers ? 1 : 0,
        blend,
      );
      if (visibility <= 0.001) continue;
      const opacity =
        visibility *
        Math.min(1, 2.4 / mix(scene.layers, nextScene.layers, blend));
      context.beginPath();
      for (let point = 0; point <= 512; point++) {
        const position = point / 512;
        const from = patternPoint(
          scene.pattern,
          position,
          layer % scene.layers,
          motion,
          signal,
        );
        const to =
          blend > 0
            ? patternPoint(
                nextScene.pattern,
                position,
                layer % nextScene.layers,
                motion,
                signal,
              )
            : from;
        const x = centerX + mix(from[0], to[0], blend) * width * breathing;
        const y = centerY + mix(from[1], to[1], blend) * height * breathing;
        points[point * 2] = x;
        points[point * 2 + 1] = y;
        if (point === 0) context.moveTo(x, y);
        else context.lineTo(x, y);
      }
      const color = context.createLinearGradient(
        0,
        height * (layer % 2),
        width,
        height * (1 - (layer % 2)),
      );
      color.addColorStop(0, paletteColor(time, layer));
      color.addColorStop(0.55, paletteColor(time, layer));
      color.addColorStop(1, paletteColor(time, layer + 1));
      context.strokeStyle = color;
      context.globalCompositeOperation = "lighter";
      context.globalAlpha =
        (0.007 + signal.energy * 0.004) * (1 - pointCloud * 0.6) * opacity;
      context.lineWidth = size * 0.018;
      context.stroke();
      context.globalAlpha = 0.045 * (1 - pointCloud * 0.6) * opacity;
      context.lineWidth = Math.max(1.5, size * 0.004);
      context.stroke();
      context.globalCompositeOperation = "source-over";
      context.globalAlpha =
        (0.58 + pulse * 0.06) * (1 - pointCloud * 0.8) * opacity;
      context.lineWidth = Math.max(0.65, size * 0.0011);
      context.stroke();

      // Quiet frequency dust follows the waves into the feedback, without
      // spawning bursts on each beat. Its fine texture is part of the trails.
      context.fillStyle = paletteColor(time, layer + 2, 12 + pointCloud * 13);
      for (let dot = 0; dot < 128; dot++) {
        const index = dot * 4;
        const level =
          signal.spectrum[Math.min(511, Math.floor(dot * 2.5))] / 255;
        const scatter = size * (0.012 + level * 0.06) * (1 - pointCloud * 0.7);
        const phase = dot * 2.39996 + motion * 0.3;
        context.globalAlpha =
          mix(0.06 + level * 0.21, 0.55 + level * 0.4, pointCloud) * opacity;
        const dotSize =
          Math.max(0.7, size / 650) * (1 + pointCloud * (0.85 + level * 0.6));
        context.fillRect(
          points[index * 2] + Math.cos(phase) * scatter,
          points[index * 2 + 1] + Math.sin(phase) * scatter,
          dotSize,
          dotSize,
        );
      }
    }
    context.globalAlpha = 1;
    context.globalCompositeOperation = "source-over";
  };
  return { draw, dispose: () => feedback?.dispose() };
}
