import { RefObject, useEffect, useRef } from "react";
import { AudioAnalysis, createAudioAnalysis } from "./audioAnalysis";
import { createClassicVisualizer } from "./classicVisualizer";

interface AudioVisualizerProps {
  mediaRef: RefObject<HTMLMediaElement>;
}

export function AudioVisualizer({ mediaRef }: AudioVisualizerProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const analysisRef = useRef<AudioAnalysis>();

  useEffect(() => {
    const canvas = canvasRef.current;
    const media = mediaRef.current;
    if (!canvas || !media || typeof CanvasRenderingContext2D === "undefined")
      return;
    const context = canvas.getContext("2d", { alpha: false });
    if (!context) return;

    const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
    const visualizer = createClassicVisualizer(canvas, context);
    const { draw } = visualizer;
    let frame: number | undefined;
    let lastTime = 0;
    let nextFrameTime = 0;
    let playing = !media.paused && !media.ended;
    let visible = false;

    const resumeAudio = () => {
      if (media.paused) return;
      if (!analysisRef.current && !reducedMotion.matches) {
        analysisRef.current = createAudioAnalysis(media);
      }
      analysisRef.current?.resume();
    };
    const animate = (now: number) => {
      const interval = 1000 / 30;
      if (now >= nextFrameTime - 0.5) {
        draw(
          Math.min((now - lastTime) / 1000, 0.1),
          analysisRef.current?.analyser,
        );
        lastTime = now;
        nextFrameTime +=
          interval *
          Math.max(1, Math.floor((now - nextFrameTime) / interval) + 1);
      }
      frame = requestAnimationFrame(animate);
    };
    const updateAnimation = () => {
      if (frame !== undefined) cancelAnimationFrame(frame);
      frame = undefined;
      if (playing && visible && !document.hidden && !reducedMotion.matches) {
        lastTime = performance.now();
        nextFrameTime = lastTime + 1000 / 30;
        frame = requestAnimationFrame(animate);
      }
    };
    const resize = () => {
      const bounds = canvas.getBoundingClientRect();
      visible = bounds.width > 0 && bounds.height > 0;
      if (visible) {
        const scale = Math.min(
          window.devicePixelRatio || 1,
          1.5,
          1280 / bounds.width,
          720 / bounds.height,
        );
        canvas.width = Math.round(bounds.width * scale);
        canvas.height = Math.round(bounds.height * scale);
        draw(1 / 30);
      }
      updateAnimation();
    };
    const start = () => {
      playing = !media.paused && !media.ended;
      resumeAudio();
      updateAnimation();
    };
    const stop = () => {
      playing = false;
      updateAnimation();
    };
    const onMotionChange = () => {
      resumeAudio();
      updateAnimation();
    };

    media.addEventListener("play", start);
    media.addEventListener("playing", start);
    const stopEvents = ["pause", "ended", "waiting", "emptied", "error"];
    stopEvents.forEach((event) => media.addEventListener(event, stop));
    document.addEventListener("visibilitychange", updateAnimation);
    document.addEventListener("pointerdown", resumeAudio, { passive: true });
    document.addEventListener("keydown", resumeAudio);
    if (typeof reducedMotion.addEventListener === "function") {
      reducedMotion.addEventListener("change", onMotionChange);
    } else {
      reducedMotion.addListener(onMotionChange);
    }
    const observer =
      typeof ResizeObserver !== "undefined"
        ? new ResizeObserver(resize)
        : undefined;
    observer?.observe(canvas);
    window.addEventListener("resize", resize);
    resize();
    resumeAudio();

    return () => {
      if (frame !== undefined) cancelAnimationFrame(frame);
      visualizer.dispose();
      observer?.disconnect();
      window.removeEventListener("resize", resize);
      media.removeEventListener("play", start);
      media.removeEventListener("playing", start);
      stopEvents.forEach((event) => media.removeEventListener(event, stop));
      document.removeEventListener("visibilitychange", updateAnimation);
      document.removeEventListener("pointerdown", resumeAudio);
      document.removeEventListener("keydown", resumeAudio);
      if (typeof reducedMotion.removeEventListener === "function") {
        reducedMotion.removeEventListener("change", onMotionChange);
      } else {
        reducedMotion.removeListener(onMotionChange);
      }
      // React StrictMode replays effects on the same media element. Keep its
      // source attached during that replay; a media element can only bind once.
      queueMicrotask(() => {
        if (!media.isConnected) {
          analysisRef.current?.dispose();
          analysisRef.current = undefined;
        }
      });
    };
  }, [mediaRef]);

  return (
    <canvas
      ref={canvasRef}
      role="img"
      aria-label="Classic audio visualizer"
      style={{
        display: "block",
        width: "100%",
        height: "100%",
        minHeight: 0,
        background: "#000",
      }}
    />
  );
}
